COLLDATA("tadabburur","ur",[[410,"§الروم\ndeeds\nالله تعالىٰ سے حسن خاتمہ كى دعا كریں.\nالله تعالىٰ کی بارگاہ میں اپنے تمام گناہوں سے توبہ کرلیں اس دن كے آنے سےپہلے جب كوئى توبہ فائده نہیں پہونچائےگا.\nدعا كریں كہ الله تعالىٰ آپ كے دل كو پاك ركھے اور اسے اپنے دین پر ثابت ركھے.\nguid\nمحتاط رہیں كہیں آپ كى قوتِ جوانى اور صحت غفلت اور لہو ولعب میں ضائع (نہ) ہوجائیں.\nعلم الله كى طرف سے ایك عطیہ ہے، جبكہ محنت اور ذہانت صرف ایك سبب ہے، لہذا یہ دعا كرتےرہیں: (رب زدنى علما) (اے میرے رب! میرے علم میں اضافہ فرما).\nانسان كى سب سے برى حالت اس وقت ہوتى ہے جب كثرت گناه سے اس كے دل پر مہرلگادی جاتی ہے، پھر وه نہ تو كچھ سمجھ پاتا ہے اور نہ ہى كچھ سوچ پاتا ہے.\nrefl\n۞ٱللَّهُ ٱلَّذِي خَلَقَكُم مِّن ضَعۡفٖ ثُمَّ جَعَلَ مِنۢ بَعۡدِ ضَعۡفٖ قُوَّةٗ ثُمَّ جَعَلَ مِنۢ بَعۡدِ قُوَّةٖ ضَعۡفٗا وَشَيۡبَةٗۚ يَخۡلُقُ مَا يَشَآءُۚ وَهُوَ ٱلۡعَلِيمُ ٱلۡقَدِيرُ ٥٤\nآیت میں صفت علم اور قدرت كا ذكر ہوا ہے ؛ كیونكہ نشو ونما اور ترقى حكمت کی متقاضى ہے، اورحکمت كا تعلق علم سے ہے(اور اس کو پختہ طور پر وجود میں لانا قدرت کی عکاسی ہے)(ابن عاشور: ۲۱؍۱۲۸)\nآیت کو ان دونوں صفات: (العليم القدير) پر ختم کرنے كى كیا مناسبت ہے؟\n۞ٱللَّهُ ٱلَّذِي خَلَقَكُم مِّن ضَعۡفٖ ثُمَّ جَعَلَ مِنۢ بَعۡدِ ضَعۡفٖ قُوَّةٗ ثُمَّ جَعَلَ مِنۢ بَعۡدِ قُوَّةٖ ضَعۡفٗا وَشَيۡبَةٗۚ يَخۡلُقُ مَا يَشَآءُۚ وَهُوَ ٱلۡعَلِيمُ ٱلۡقَدِيرُ ٥٤\n(خلقكم من ضعف) تم كو كمزورى سے پیدا كیا: پہلى كمزوری حقیر پانى (منی)سے انسان كى پیدائش اور بچپن میں اسكا ناتواں ہونا ہے۔ اور دوسرى آخری كمزورى بڑھاپا ہے۔ (ابن جزى: ۲؍۱۷۱)\nآیت میں دونوں كمزورى سے كیا مراد ہے؟ اس كى وضاحت كریں.\nوَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يُقۡسِمُ ٱلۡمُجۡرِمُونَ مَا لَبِثُواْ غَيۡرَ سَاعَةٖۚ\nالله تعالىٰ دنیا وآخرت ہر دو جگہ كافروں كى نادانى كے بارے میں بتا رہا ہے، چنانچہ انہوں نے دنیا میں عبادت بھى كى تو بتوں كى ، اور آخرت میں بھى بڑى نادانى كریں گے جیسے وه قسم كھا كر كہیں گے كہ وه دنیا میں ایك گھڑى سے زیاده نہیں ٹھہرے، جس سے ان كا مقصد یہ ہوگا كہ نہ ہی ان پر حجت قائم ہوسکی اور نہ ہی انہیں مہلت مل سكى کہ ان کا عذر ختم ہوسکے۔ (ابن كثیر: ۴۲۴)\nآیت سے دنیا وآخرت ہر دو جگہ كافروں كى نادانى كا پتہ چلتا ہے، اس كى وضاحت كریں.\nوَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَٱلۡإِيمَٰنَ لَقَدۡ لَبِثۡتُمۡ فِي كِتَٰبِ ٱللَّهِ إِلَىٰ يَوۡمِ ٱلۡبَعۡثِۖ فَهَٰذَا يَوۡمُ ٱلۡبَعۡثِ وَلَٰكِنَّكُمۡ كُنتُمۡ لَا تَعۡلَمُونَ ٥٦\nایمان كو اس كى اہمیت كے پیش نظر علم پر عطف كیا گیا ؛ كیونكہ بغیر ایمان كے علم ایسے سچے عقیدے كى طرف رہنمائى نہیں كرسكتا جن سے اخروى زندگى میں كامیابى مل سكے۔(ابن عاشور: ۲۱؍۱۳۱)\nآیت كریمہ كے اندر ایمان كو علم پر عطف كیوں كیا گیا ہے؟\nكَذَٰلِكَ يَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِينَ لَا يَعۡلَمُونَ ٥٩\nیعنى الله تعالىٰ جو عظمت والا اور بلند قدرت والا ہے ان لوگوں كےدلوں پر مہر لگا دےگا جو نادان ہیں، یعنى جو علم حاصل نہیں كرتے ہیں اور نہ ہى حق كى تلاش کرتے ہیں، بلكہ ان ہی خرافات پر بضد ہیں جنہیں دل میں بٹھا ركھا ہے، اور ایسے واہیات كاموں میں پڑےہوئے ہیں جنہیں انہوں نے خود ایجاد كر ركھا ہے؛ كیونكہ جہل مركب حق کی معرفت میں ركاوٹ ہے، اور حق گو كے جھٹلانے كا سبب بنتا ہے ، اسى لئے كہا گیا كہ جہل مركب جہل بسیط سے بھى برا ہے۔ (الألوسى: ۱۱؍۶۰- ۶۱) (توضیح از مترجم: جہل مرکب وہ ہے کہ آدمی جہالت کے باوجود اپنے آپ کو جاہل نہ سمجھے اور جہل بسیط وہ ہے کہ آدمی اپنے آپ کو جاہل سمجھے)\nحق كى عدم تلاش اور جہالت پر اصرار كى خطرناكى کوواضح كیجئے.\nفَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ\nاور یہى چیز(وعدہ الٰہی کی حقانیت کا یقین) صبر كیلئے معاون ہے؛ كیونكہ جب بندے كو معلوم ہے کہ اسكا عمل ضائع نہیں ہوگا بلكہ وه اسے پورا پوار ضرور پائےگا تو عمل كے راستے میں درپیش ساری تکلیفیں اس کے سامنے ہیچ ہوجاتی ہیں، اور اس پر ساری مشقتیں آسان ہوجاتی ہیں۔(السعدى: ۶۴۶)\nالله كے وعدے كى حقانیت كے ذکر سے پہلے صبر كا ذكر كیوں كیا گیا؟\nوَلَا يَسۡتَخِفَّنَّكَ ٱلَّذِينَ لَا يُوقِنُونَ ٦٠\nیہاں اس بات كا پتہ چلتا ہے كہ یقین كامل والا مومن سنجیده عقل والا ہوتا ہے جسے صبر كرنا بہت آسان ہوتاہے، اور ہر كمزور یقین والا كمزوراور ہلکے عقل والا ہوتا ہے، اس طرح پہلا مغز كے درجے میں ہے جبكہ دوسرا چھلکے كے درجے میں۔(السعدى: ۶۴۶)\nیہ آیت آزمائش میں مبتلا لوگوں كى عقلوں كے مختلف ہونے كا پتہ دیتى ہے ، اس كى وضاحت كریں.\nwords\nمُصفَرًّاوه سبز هونے كے بعد پيلا هوكر خراب هونے لگا.\nوَشَيبَةًبڑھاپا / بڑي عمر.\nوَلاَ هُم يُستَعتَبُونَان كي اطاعت او رتوبه سے الله كي رضامندي نهيں طلب كي جاتي.\nوَلاَ يَستَخِفَّنَّكَتمهيں غصه ميں نه لائے۔ / پست نه كريں گي."],[411,"§لقمان\ndeeds\nپانچوں وقت كى نمازیں باجماعت تكبیرۂ تحریمہ كے ساتھ ادا كریں.\nایك پیغام بھیجیں جس میں گانے كى خطرناكى بیان كریں ، اور یہ بھی كہ گانا راه حق سے بھٹکاتا ہے.\nخلق خدا اور اتباع شریعت كے خلاف تكبر كرنے سے الله كى پناه مانگئے.\nguid\nقرآن كى اتباع كرنے سے بنده جو فوائد حاصل كرتا ہے انہیں فوائد میں سے ہدایت، رحمت اور احسان كے مرتبے كا حصول ہے.\nجو گانا سنتا ہے اسكا دل قرآن كى محبت سے ہٹ جاتا ہے.\nتواضع وخاكسارى اتباع حق كیلئے مددگار ہوتا ہے جبكہ تكبر اور گھمنڈ اسكے برعكس.\nrefl\nتِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡحَكِيمِ ٢ هُدٗى وَرَحۡمَةٗ لِّلۡمُحۡسِنِينَ ٣\nیہ كتاب حكمت والی ہے، ہر عمده اخلاق كى طرف دعوت دیتی ہے اور برے اخلاق سے روکتی ہے، اس کے باوجود اكثر لوگ اس كى ہدایت سے محروم ہیں، اس پر ایمان لانے اور عمل كرنے سے اعراض كرتےہیں، سوائے اس کے جسے اللہ توفیق دے دے اور اسے برائیوں سے بچادے، اور یہی وہ لوگ ہیں جو اپنے رب كى عبادت میں اور خلق خدا كے ساتھ مخلص ہوتےہیں۔(السعدى: ۶۴۶)\nاس كتاب حكیم كے تعلق سے لوگوں كا كیا موقف ہے؟\nٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ\nیہاں اعمال میں سے دو بہترین اعمال كا خصوصى طور سے ذكر فرمایا: پہلا عمل: نماز جو اخلاص، رب سے سرگوشی، دل، زبان اور تمام اعضاء کی عبادت گذاری پر مبنی ہے، اور دیگر نیک اعمال کے لئے معاون ہے۔اور دوسرا عمل: زکاۃ جو اداکرنے والوں کو گھٹیا صفات سے صاف ستھرا بنادیتی ہے، اور مسلمان بھائی کو نفع پہنچاتی ہے، اور اس کی ضرورت پورى کرتی ہے،اور اس سے یہ بھى واضح ہوتا ہے كہ بندۂ مومن الله تعالىٰ كى محبت كو مال كى محبت پر ترجیح دیتاہے، چنانچہ وه اپنے محبوب مال كو اس كى خاطر خرچ كرتاہے جو اسے اپنے مال سے كہیں زیاده محبوب ہے اوروه ہے الله تعالىٰ كى رضا۔(السعدى: ۶۴۶)\nدوسرے تمام اعمال كو چھوڑ كر ان ہی دو اعمال كا خصوصى طور پر ذكر كیوں كیا گیا؟\nٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ ٤\n(الذين يقيمون الصلاة) جو لوگ نماز قائم كرتےہیں، یعنى اسے ایسا بنا دیتےہیں گویا وه اپنے افعال کے ساتھ كھڑى ہو (اور اس کا وجود پورے طور پر نمایاں ہو) بایں طور کہ جن چیزوں کو نماز میں کرنے کا حکم دیاگیا ہے یا ترغیب دی گئی ہے، یا جن پر وہ (نماز) کسی اعتبار سے موقوف ہے ان سب کو وہ بڑی عمدگی سے انجام دیتے ہیں اور اسے مناسب اوقات میں (اسی عمدگی کے ساتھ) ہمیشہ اداکرتے ہیں۔(البقاعى: ۱۵؍۱۴۴)\n(يقيمون الصلاة)كى تعبیر كیا فائده دیتی ہے؟\nوَمِنَ ٱلنَّاسِ مَن يَشۡتَرِي لَهۡوَ ٱلۡحَدِيثِ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّخِذَهَا هُزُوًاۚ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ ٦\nابو صہباء بكرى نے كہا: میں نے اس آیت كے بارے میں ابن مسعود رضی اللہ عنہ سے سوال كیا تو آپ نے فرمایا:قسم اس اللہ کی جس کے علاوہ کوئی معبود برحق نہیں اس سے گانا مراد ہے، اور اپنی یہ بات تین بار دہرائی۔اور ابراہیم نخعى نے كہا: گانا دل میں نفاق پیدا كرتاہے.اور كہا گیا: گانا زنا كا رقیہ (منتر)ہے۔ (البغوى: ۳؍۵۰۶)\nاس آیت كى روشنى میں سلف كے اقوال سے گانے كى خرابیاں اور اسكے خطرات كى وضاحت كیجئے.\nوَمِنَ ٱلنَّاسِ مَن يَشۡتَرِي لَهۡوَ ٱلۡحَدِيثِ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّخِذَهَا هُزُوًاۚ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ ٦\n(لهو الحديث) (اس سے مراد) غافل کردینے والی نت نئی لذت بخش چیزیں جن کے ذریعہ وقت گزاری ہوتی ہے، جیسے گانا، ہنسانے والی چیزیں، اور بےسود و بے اعتبار دیگر چیزیں، چنانچہ یہ چیزیں نفس کو لذت سے خالص بہیمانہ طبیعت تک پہونچادیتی ہیں، پس اسے نہایت عبث قسم کے کھیل کود پر آمادہ کرتی ہیں، جیسے ناچنا وغیرہ۔سو ایسا شخص نیچ کی گہری کھائی میں جاگرتا ہے، جس طرح اس سے پہلے والی آیت میں مذکور شخص اپنی حکمت کی وجہ سے اعلیٰ درجات تک پہنچاتھا۔(البقاعى: ۱۵؍۱۴۶)\nلہو ولعب میں پھنسنے كا كیا خطره ہے؟\nوَمِنَ ٱلنَّاسِ مَن يَشۡتَرِي لَهۡوَ ٱلۡحَدِيثِ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّخِذَهَا هُزُوًاۚ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ ٦\nقتاده نے كہا: اللہ کی قسم ،ممكن ہے آدمى اسكے لئے مال خرچ نہ كرے، لیکن اسے اچھا سمجھنا ہى اسكا خریدنا ہے، آدمى کی گمراہى كے لئے کافی ہے کہ حق باتوں پر باطل كو اور نفع بخش پر نقصان دہ كو ترجیح دے۔(ابن كثیر: ۳؍۴۲۶)\nکیا اس آیت کے ضمن میں شامل ہونے کے لئے ضروری ہے کہ لہو ولعب كى چیزوں كو خریدنے كیلئے آدمى مال ہى خرچ كرے؟\nأُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ ٦\nیعنى جس طرح انہوں نے الله كى آیتوں كو اور اسكے راستے كوحقیر سمجھا اسى طرح قیامت كے دن ہمیشہ ہمیش رہنے والے عذ۱ب میں انہیں ڈال كر ذلیل كیا جائےگا۔(ابن كثیر: ۳؍۴۲۶)\nان لوگوں كا بدلہ ان كے عمل كے ہى جنس سے ہوگا، اسكى وضاحت كریں.\nwords\nهُزُوًاٹھٹھه و مذاق.\nوَقرًابهرا پن / بوجھ.\nرَوَاسِيَثابت پهاڑ.\nأَن تَمِيدكه وه حركت نه كرے.\nوَبَثَّاور نشر كيا/ پھيلايا."],[412,"§لقمان\ndeeds\nآج گھریلو کاموں میں سے كوئى ایسا كام كریں جسے آپكى والده كرتى ہوں تاكہ ان كے صبر اور انكى فضیلت كا اندازه كرسكیں.\nنماز کے وقت آپ جن لوگوں کو راستے میں بیٹھاہوادیکھیں انہیں نماز کی ادائیگی کی یاد دلائیں.\nپست آواز میں بات كریں، چیخ وپكار کرنے والے اور دوسروں کو تنگ کرنے والے نہ بنیں.\nguid\nخالق كى معصیت (نافرمانی) میں كسى مخلوق كى اطاعت (فرمانبرداری)نہیں ہے، یہ اصول غیر معصیت میں والدین كےساتھ حسن سلوك کے منافی (مخالفت) نہیں ہے.\nآپ ان ربانی علماء کے راستے پر چلیں جواللہ کی طرف رجوع کرنے والے ہیں.\nتنہائیوں كے گناہوں سے بچ كررہیں.\nrefl\nوَلَقَدۡ ءَاتَيۡنَا لُقۡمَٰنَ ٱلۡحِكۡمَةَ أَنِ ٱشۡكُرۡ لِلَّهِۚ وَمَن يَشۡكُرۡ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ حَمِيدٞ ١٢\nلقمان علیہ السلام کو جو حکمت سب سے پہلے تلقین کی گئی تھی اس حکمت کا تعلق ان کی ذات سے تھا کہ اللہ نے انہیں حکم دیا کہ وہ اللہ کی جن نعمتوں کی آغوش میں ہیں ان پر اللہ کا شکر اداکریں، اور ان ہی نعمتوں میں سے انكا الله كا برگزیده بنده ہونا بھى ہے۔(ابن عاشور: ۲۱؍۱۵۲)\nآیت كریمہ كى روشنى میں لقمان علیہ السلام كى سب سے پہلى حكمت كیا تھى؟\nوَإِذۡ قَالَ لُقۡمَٰنُ لِٱبۡنِهِۦ وَهُوَ يَعِظُهُۥ يَٰبُنَيَّ لَا تُشۡرِكۡ بِٱللَّهِۖ إِنَّ ٱلشِّرۡكَ لَظُلۡمٌ عَظِيمٞ ١٣\nلقمان علیہ السلام نے اپنے بیٹے کو جو نصیحت کی اس کے آغاز میں یہ طلب کیا کہ اللہ کے ساتھ شرک کرنے سے بازرہنا، اور ایسا اس لئے کہ جس نفس کو پاک کرنا اور کمال تک پہنچانا ہو اس کے لئے ضروری ہے کہ پہلے اسے فساد و بگاڑ کے مبادیات سے صاف و ستھرا کیاجائے۔(ابن عاشور: ۲۱؍۱۵۵)\nلقمان علیہ السلام نے اپنے بیٹے كو سب سےپہلے شرك سے منع كیوں كیا؟\nوَإِذۡ قَالَ لُقۡمَٰنُ لِٱبۡنِهِۦ\nلقمان علیہ السلام اپنے لڑكے كو نصیحت كررہےہیں جو كہ لوگوں میں سب سے زیاده ان کی شفقت كا مستحق ہے، اور ان کے نزدیک سب سے زیادہ محبوب ہے لہٰذا وہ اس بات کا حقدار بھی ہے کہ (لقمان علیہ السلام بحیثیت باپ) اپنے سب سے افضل علم و معرفت سے اسےنوازیں۔(ابن كثیر: ۳؍۴۲۸)\nلقمان علیہ السلام کی نصیحتیں بیٹے کے لئے تھیں، اس سے کیا فائدہ حاصل ہوتا ہے؟\nوَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ حَمَلَتۡهُ أُمُّهُۥ وَهۡنًا عَلَىٰ وَهۡنٖ وَفِصَٰلُهُۥ فِي عَامَيۡنِ\nیہاں اللہ تعالیٰ والدہ کی پرورش و پرداخت، اور شب و روز جاگنے میں ان کی مشقت اور تکان کا ذکرکررہا ہے تاکہ بچے کو اس (بےمثال) حسن سلوک کو یاد دلائے جو ماں نے اس کے لئے پیش کیا ہے۔(ابن كثیر: ۳؍۴۲۹)\nالله تعالىٰ نے اولاد كى تربیت میں ماں كى مشقت كو ذكر كیوں كیا ؟\nأَنِ ٱشۡكُرۡ لِي وَلِوَٰلِدَيۡكَ إِلَيَّ ٱلۡمَصِيرُ ١٤\nكہا گیاہے: الله كا شكریہ ایمان كى نعمت پر ہے اور والدین كا شكریہ تربیت كى نعمت پر ہے، اور سفیان بن عیینہ رحمہ اللہ نے كہا: جس نے پانچ اوقات كى نماز پڑھى اس نے الله كا شكریہ ادا كردیا، اور جس نے نمازوں كےبعد والدین كیلئے دعا كى اس نے ان کا شكریہ ادا كردیا۔(القرطبى: ۱۶؍۴۷۵)\nالله کا شکر اور والدین كا شكر ادا كیسے ہوگا؟\nوَأۡمُرۡ بِٱلۡمَعۡرُوفِ وَٱنۡهَ عَنِ ٱلۡمُنكَرِ وَٱصۡبِرۡ عَلَىٰ مَآ أَصَابَكَۖ\nلقمان علیہ السلام کومعلوم تھا كہ بھلائى كا حكم دینے والوں اور برائى سے روكنے والوں کو لوگوں كى طرف سے تكلیف پہونچتی ہے اسى لئےانہوں نے اپنے بیٹے کو صبر كرنے كا حكم دیا ۔(ابن كثیر: ۳؍۴۳۰)\nلقمان علیہ السلام نے اپنے بیٹے کو بھلائی کا حکم کرنے اور برائی سے روکنے کا حکم دینے کے بعد صبر کا حکم کیوں دیا؟\nوَٱقۡصِدۡ فِي مَشۡيِكَ وَٱغۡضُضۡ مِن صَوۡتِكَۚ إِنَّ أَنكَرَ ٱلۡأَصۡوَٰتِ لَصَوۡتُ ٱلۡحَمِيرِ ١٩\nیعنى چال میں میانہ روى ہونا چاہیئے، نہ ہى اكڑ كر اور نہ ہى جلدى جلدى، اور عطاء نے كہا: پروقار اور اطمینان وسكون سے چلو جیسا كہ ارشاد بارى ہے: ﴿يَمۡشُونَ عَلَى ٱلۡأَرۡضِ هَوۡنٗا﴾ (الفرقان: ۶۳) (الله كےبندے زمین پر فروتنى سے چلتےہیں) (البغوى: ۳؍۵۱۱)\nچلنے میں كیسى حكمت اپنانى چاہیئے ؟\nwords\nوَهنًاكمزوري.\nوَفِصَالُهُدودھ چھڑانا.\nأَنَابَرجوع كيا/ توبه كي.\nحَبَّةٍ مِن خَردَلٍانتهائي چھوٹا دانا۔ رائي كا دانا.\nمِن عَزمِ الأُمُورِوه امور جن كا حريص هونا چاهيے.\nوَلاَ تُصَعِّر خَدَّكَاپنے گال نه چڑھائيں / تكبر سے اور بڑائي ٍسے.\nمَرَحًااتراتے هوئے / تكبر كرتے هوئے."],[413,"§لقمان\ndeeds\nقرآن كى كوئى سورت لیجئے اور اس پر طلب علم كے تینوں مراتب كى تطبیق دیجئے ، اور وه تینوں مراتب یہ ہیں: (ا) اس میں جو فوائد ہیں ان پر غوروفکر کرنا (ب) اپنے سے بڑے علم والے كےساتھ مل كر اسكا مذاكره کرنا ، (ج) كسى تفسیر كى كتاب سے اسكى تفسیر پڑھنا.\nكسى ورق پر بعض ان ظاہرى اور باطنى نعمتوں كو لکھیں جو الله نے آپ پر كرركھى ہیں، تاكہ یہ عمل شكریہ اداكرنے میں معاون ہو.\nایك پیغام بھیجئے جس میں بغیر علم كے بحث ومباحثہ كرنے كى سنگینى كو واضح كیجئے.\nguid\nاندهى تقلید کرنا اور عقل سے كام نہ لینا نقصان ده ہے.\nدین كو مضبوطى سے پكڑنا ہى نجات کا باعث اورامن و امان کا محافظ ہے.\nبنده صرف دعوت الٰہی کی تبلیغ كا مكلف ہے، نتائج كا معاملہ الله كے ہاتھ میں ہے.\nrefl\nأَلَمۡ تَرَوۡاْ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَأَسۡبَغَ عَلَيۡكُمۡ نِعَمَهُۥ ظَٰهِرَةٗ وَبَاطِنَةٗۗ\nآپ کا كام یہى ہے كہ ان نعمتوں پر الله كا شكریہ ادا کریں، بایں طور کہ نعمتوں سے نوازنے والے سے محبت کریں، اسكى اطاعت میں لگ جائیں، اور ان نعمتوں کو اللہ کی اطاعت میں معاون کے طور پر استعمال کریں اور کسی بھی نعمت سے اللہ کی معصیت میں مدد نہ لیں۔(السعدى: ۶۴۹)\nنعمتوں كا شكریہ ادا كیسے ہوگا؟\nوَأَسۡبَغَ عَلَيۡكُمۡ نِعَمَهُۥ ظَٰهِرَةٗ وَبَاطِنَةٗۗ\n(نعمه ظاهرة وباطنة) ظاہرى اور باطنى نعمت: ظاہرى نعمت میں صحت اور مال وغیره آئےگا، جبكہ باطنى نعمت میں وه سارى نعمتیں آئیں گى جو انسانى نظروں سے اوجھل ہوتى ہیں جیسے برائیوں پر پرده پوشى وغیره۔(ابن جزى: ۲؍۱۷۴)\nبعض ظاہرى اور باطنى نعمتوں كى مثال دیجیئے.\nوَأَسۡبَغَ عَلَيۡكُمۡ نِعَمَهُۥ ظَٰهِرَةٗ وَبَاطِنَةٗۗ\nابن عباس رضی اللہ عنہ سے مروى ہے: ظاہرى نعمت سے مراد اسلام اور قرآن ہے، جبكہ باطنى نعمت سے مراد یہ ہے کہ اللہ نے آپ کے گناہوں پر پردہ ڈال رکھا ہے، اور فوری طور پر اس کی سزا نہیں دے رہا ہے، اور ضحاک نے كہا: ظاہرى نعمت سے مراد بہترین شکل و صورت اور جسمانى اعضاء كى درستگى ہے جبكہ باطنى نعمت سے مراد علم ومعرفت ہے۔(القرطبى : ۳؍۵۱۲)\nدو ایسى نعمتوں كا ذكر كریں جن كےبارے میں سمجھتےہوں كہ الله نے خصوصی طور پر آپ کو نواز ا ہے.\nوَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَلَا هُدٗى وَلَا كِتَٰبٖ مُّنِيرٖ ٢٠\nفرمانِ الٰہی (بغير علم ولا هدى ولا كتاب منير) حصول علم كے مراتب كو شامل ہے: حصول علم میں جدوجہد كرنا، یا عالم سے براہ راست سیکھنا، یا صحیح (اور معتبر) كتابوں کا مطالعہ كرنا۔(ابن عاشور: ۲۱؍۱۷۵)\nآیت كریمہ میں حصول علم كے تین مراتب بتائےگئےہیں، ان كى وضاحت كریں.\n۞وَمَن يُسۡلِمۡ وَجۡهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحۡسِنٞ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰۗ وَإِلَى ٱللَّهِ عَٰقِبَةُ ٱلۡأُمُورِ ٢٢\nیعنى الله كى عبادت اور اسكى طرف متوجہ ہونے میں مخلص ہوتاہے، (وهو محسن) اور ساتھ ہى محسن بھى ہوتاہے كیونكہ عبادت بغیر احسان اور قلبى معرفت كے بے سود ہوتی ہے۔(القرطبى: ۱۶؍۴۸۷)\nاپنے آپ کو اللہ کے تابع کیسے کریں گے؟ اور اس (تابع ہونے) کے ساتھ احسان کی قید کیوں لگائی گئی؟\n۞وَمَن يُسۡلِمۡ وَجۡهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحۡسِنٞ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰۗ وَإِلَى ٱللَّهِ عَٰقِبَةُ ٱلۡأُمُورِ ٢٢\nآیت کو (إن الله عليم بذات الصدور) پر ختم کیاگیا ہےاس کی مناسبت یہاں یہ ہے کہ مشركین كا بعض کفر علانیہ ہوتاہے اور بعض پوشیده ۔(ابن عاشور: ۲۱؍۱۷۸)\nآیت كریمہ كو اس جملے (إن الله عليم بذات الصدور) پر ختم كرنے كى كیا مناسبت ہے؟\nوَلَوۡ أَنَّمَا فِي ٱلۡأَرۡضِ مِن شَجَرَةٍ أَقۡلَٰمٞ وَٱلۡبَحۡرُ يَمُدُّهُۥ مِنۢ بَعۡدِهِۦ سَبۡعَةُ أَبۡحُرٖ مَّا نَفِدَتۡ كَلِمَٰتُ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ ٢٧\nآیت كےاندر الله كے كلمات كى كثرت كى خبر دى گئى ہے، اور مراد الله كے علم كى وسعت ہے۔ اور آیت كا مفہوم ہے: زمین كے سارے درخت اگر قلم ہوجائیں، سارے سمندر روشنائى ہوجائیں اور ان سمندروں میں مزید سات سمندر ہمیشہ ہمیش بہایاجاتا رہے اور ان سے الله كے كلمات كو لكھا جائے، تو سارے درخت اور سمندر ختم ہوجائیں گے پر الله كے كلمات ختم نہیں ہوں گے؛ كیونكہ درخت اور دریا زوال پزیر ہیں جبكہ الله كے كلمات لازوال ہیں۔ (ابن جزى: ۲؍۱۷۵)\nاس آیت سے ایك فائده ذكر كریں.\nwords\nسَخَّرَ لَكُماس نے تمهارے ليے مسخر كيا/ پست كيا.\nوَأَسبَغَاور تم پر عمومي نعمتوں كي برسات كي.\nبِالعُروَةِ الوُثقَىالله تعاليٰ تك رسائي كے پخته أسباب.\nعَاقِبَةُمرجع / انجام.\nغَلِيظٍموٹا/ بھاري."],[414,"§لقمان\ndeeds\nكشتیوں كى كچھ تصویروں كا مشاہده كریں، یا ان كے بارے میں کچھ پڑھیں تاكہ ہم پر الله كى جو یہ عظیم نعمت ہے اس سے آگاه ہوسكیں.\nكسى ایسے سخت موقف كو یاد كریں جس سے الله نے آپكو نجات دى ہو، اورنجات کی نعمت پر الله كا حمد و شکر ادا كریں، پھر شكریہ كے طور پر كوئى نیك عمل كریں.\nدنیاوى زیب وزینت كى چیزوں میں سے كسى ایسى چیز كو یاد كریں جو آپ كے دل سے لگى ہو، پھر اس كے تین عیوب كو لکھیں تاکہ آپ کا قلبی تعلق اس سے ہلکا اور کمزور ہو.\nguid\nاس زمانے كے بعض مشركین كفار قریش سے بھى زیاده سخت ہیں؛ كیونكہ یہ خوشحالى اور سختى ہر دو حالتوں میں شرك كرتےہیں، جبكہ كفار قریش صرف خوشحالى كے وقت شرك كرتےتھے اور مصیبت كےوقت موحد ہوجاتے تھے (کہ صرف الله كو پكارتےتھے).\nعلم غیب كا دعوىٰ كرنا كفر ہے، اور جو گمان كرے كہ كوئى نبى یا ولى غیب جانتے ہیں تو اس نے گویا خالق كےساتھ مخلوق کے شریك ہونے کا دعویٰ کیا.\nٹال مٹول سے بچئے اور عمل كیجئے.\nrefl\nأَلَمۡ تَرَ أَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِيٓ إِلَىٰٓ أَجَلٖ مُّسَمّٗى وَأَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ خَبِيرٞ ٢٩\nابتداء رات سے كى گئى كیونكہ اس كا معاملہ نہایت عجیب ہے، دیکھیں كیسے اسكى تاریكیاں دن كى روشنى پر چھا جاتى ہیں۔ (ابن عاشور: ۲۱؍۱۸۵)\nآیت كریمہ میں رات کا ذکر پہلے کیوں کیاگیا؟\nأَلَمۡ تَرَ أَنَّ ٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِنِعۡمَتِ ٱللَّهِ لِيُرِيَكُم مِّنۡ ءَايَٰتِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ ٣١\n(صبر و شکر کرنے والے سے کنایہ مومنین ہیں) اورایمان كى تمام شاخوں میں سے یہاں صرف صبر وشكر كوکنایہ کے لئے بطور خاص ذكر كیا گیا ؛ كیونكہ سمندری سفر کی صورت میں یہى دونوں صفتیں ہى زیاده مناسب ہیں چونکہ سمندرکا مسافر خطرے اور سلامتى كے درمیان رہتا ہے اور یہ دونوں صورتیں (خطرہ اور سلامتی) صبروشکر کا مظہر ہیں (یعنی ان دونوں حالتوں میں صبر و شکر بہتر ہتھیار ہوتے ہیں)۔(ابن عاشور: ۲۱؍۱۹۰)\nسمندر میں كشتیوں كے چلنے كےذکر کے ساتھ صبر وشكر ہى كو بطور خاص كیوں لایا گیا؟\nإِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ ٣١\nیعنى اللہ کے فیصلوں پربہت زیادہ صبر كرنے والا اور اسكى نعمتوں پربہت زیادہ شكریہ ادا كرنے والا ہے، اور اہل معانى نے كہا: یہاں اس صفت (کوذکر کرکے) ہرمومن مراد لیا ہے ؛ كیونكہ صبر وشكر ایمان کی بہترین خصلتوں میں سےہیں۔(القرطبى: ۱۶؍۴۹۳)\nآیت كو ان دو عظیم صفتوں پر ختم كیوں كیا گیا؟\nأَلَمۡ تَرَ أَنَّ ٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِنِعۡمَتِ ٱللَّهِ لِيُرِيَكُم مِّنۡ ءَايَٰتِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ ٣١\nصبر و شکر ہر دو صفت کو حد درجہ اختیار کرنے والا ہو،صبر وشكر میں سے ہر ایك كو صیغۂ مبالغہ كےساتھ لایا گیا ہے، جس سے پتہ چلتا ہے كہ سختی کے زمانے کی طرح خوشحالی کے زمانے میں اللہ کی عظمت کو وہی شخص جانتا ہے جس کی طبیعت میں اللہ نے یہ خصلت ودیعت کی ہے، اسے توفیق دی ہے، اور اس کی مدد کی ہےاور وہی شخص پہلی فطرت سلیمہ کے تقاضے کے مطابق (اللہ کی عظمت کو مد نظر رکھتے ہوئے) عہد کی ہردو حال میں پاسداری کرتا ہے اور عہدشکنی نہیں کرتا اور ایسے لوگ كم ہى ہوتےہیں۔(البقاعى: ۱۵؍۲۰۶)\nآیت كے آخر میں صبر وشكر كى صفتوں كو صیغۂ مبالغہ كےساتھ لانے كا كیا فائده ہے؟\nوَإِذَا غَشِيَهُم مَّوۡجٞ كَٱلظُّلَلِ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ فَمِنۡهُم مُّقۡتَصِدٞۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا كُلُّ خَتَّارٖ كَفُورٖ ٣٢\n(ختَّار) یعنى غدار، بہت زیاده غدارى كرنے والا، كیونكہ وه الله كى نعمتوں كا انكار كرتا ہے، اور یہ بہت بڑى غدارى ہے۔(ابن جزى: ۲؍۱۷۶)\nكافر بڑا غدار كیوں ہوتاہے؟\nيَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡ وَٱخۡشَوۡاْ يَوۡمٗا لَّا يَجۡزِي وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوۡلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَيۡـًٔاۚ\nلوگوں کو الله تبارك وتعالىٰ اپنے تقوىٰ كا حكم دے رہا ہے، تقویٰ سے مراد اللہ كے احکامات كى تعمیل كرنا اور منہیات(جن چیزوں سے اللہ نے روکا ہے) كو ترك كرنا ہے۔اور الله تعالىٰ قیامت كے سخت دن كے خوف كى طرف ان كى توجہ مبذول کرارہا ہے جس روز ہر شخص كو اپنے سوا كسى كا ہم و غم نہیں ہوگا، پس معاملہ ایسا ہوگا (لا يجزي والد عن ولده ولا مولود هو جازٍ عن والده شيئًا) نہ تو باپ اپنے بیٹے كے كچھ كام آئےگا نہ بیٹا اپنے باپ كے كچھ كام آسكےگا۔ یعنى وه اسكى نیكیوں میں اضافہ كرسكےگا نہ اسكے گناہوں میں كوئى كمى كرسكےگا۔ ہر بندےكا عمل پورا ہوچكاہوگا، اور اس پر اسكى جزوسزا بھى متحقق ہوچكى ہوگى۔ لہٰذا اس مقام پر اس ہولناك دن كى طرف توجہ کرنابندے كو قوت عطا کرتا ہے اور اس كیلئے تقوىٰ كو آسان کردیتا ہے۔(السعدى:۶۵۲)\nالله تعالىٰ نے قرآن كریم میں قیامت كى ہولناكیوں كو زیاده سے زیاده كیوں بیان كیاہے؟\nإِنَّ ٱللَّهَ عِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَيُنَزِّلُ ٱلۡغَيۡثَ وَيَعۡلَمُ مَا فِي ٱلۡأَرۡحَامِۖ وَمَا تَدۡرِي نَفۡسٞ مَّاذَا تَكۡسِبُ غَدٗاۖ وَمَا تَدۡرِي نَفۡسُۢ بِأَيِّ أَرۡضٖ تَمُوتُۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرُۢ ٣٤\nآیت میں مذکور ان پانچوں امور کو حدیث نبوی میں مفاتیح الغیب (غیب کی کنجیاں) کا لقب دیا گیا ہے، اور ان ہی پانچوں امور سے فرمان الٰہی ﴿وَعِندَهُۥ مَفَاتِحُ ٱلۡغَيۡبِ لَا يَعۡلَمُهَآ إِلَّا هُوَ﴾ (الانعام: ۵۹) (یعنی : اللہ کے پاس غیب کی کنجیاں ہیں جنہیں اللہ کے علاوہ اور کوئی نہیں جانتا) کی تفسیر کی گئی ہے، چنانچہ صحیح بخاری میں ابن عمر کی روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا “مفاتيح الغيب خمس” یعنی غیب کی کنجیاں پانچ ہیں پھر آپ نے تلاوت فرمایا (اِنَّ اللّٰهَ عِنْدَهٗ عِلْمُ السَّاعَةِ) (ابن عاشور: ۲۱؍۱۹۸)\nآیت ِکریمہ میں مذکور پانچوں چیزوں کو کس چیز کا نام دیا گیا ہے؟\nwords\nيُولِجُوه داخل كرتا هے۔ كبھي رات لمبي اور كبھي دن لمبا ۔ ايك كا حصه دوسرے كو ديا جاتا هے.\nغَشِيَهُمان كو ڈھانك ليا۔ ان پر بلند هوا.\nكَالظُّلَلِبادلوں كي طرح ؛ يا سايه فگن پهاڑ.\nخَتَّارٍغدار / وعده توڑنے والا."],[415,"§السجدہ\ndeeds\nاپنى مسجد كے امام كو یاد دلائیں كہ جمعہ كى فجر میں سورۂ سجده سورہ انسان (دہر) کے ساتھ پڑھیں کیونکہ یہى سنت ہے.\nدعا كریں كہ الله تعالىٰ آپ كے معاملات كى تدبیر كرے اور علم نافع سے نوازے كہ وہى مدبر وعلیم ہے.\nدعا كریں كہ الله تعالىٰ آپكے اخلاق كو بہتر بنائے جس طرح آپكى تخلیق بہتر بنائى ہے.\nguid\nآیت كے اندر معاملات كى تدبیر میں الله كى عظیم قدرت كا بیان ہے.\nآنكھ اوركان الله كى دونعمتیں ہیں ، اور ان پر الله كا شكریہ اس طرح ہو سكتا ہے كہ ان كا استعمال ان چیزوں میں کیاجائے جو الله كے قریب كرتےہوں.\nوفات كے ان لمحات كو یاد كریں جن میں آپ اپنے عمل کے ساتھ اللہ کے سامنے ہوں گے چاہے خیر ہو یا شر.\nrefl\nالٓمٓ ١ تَنزِيلُ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ ٢\nابو ہریره رضی اللہ عنہ سےروایت ہے كہ نبى كریم صلی اللہ علیہ وسلم جمعہ كےدن فجر میں ﴿الٓمٓ * تَنزِيلُ﴾ السجدۃ اور ﴿هَلۡ أَتَىٰ عَلَى ٱلۡإِنسَٰنِ﴾. پڑھتےتھے۔ (ابن كثیر: ۶؍۳۵۸)\nسورۂ سجده پر غوروفكر كریں پھر جمعہ كى فجر میں اسكے پڑھنے كے استحباب كى حكمت بیان کرنے کی کوشش کریں.\nتَنزِيلُ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ ٢\nیہ كتاب كریم اس رب كائنات كى طرف سے نازل کی ہوئی ہے جس نے اپنى نعمت كے ذریعے سے سارے جہاں کی پرورش کی ہے۔اور سب سے بڑى چیز جس كے ذریعے الله تعالىٰ نے اپنى ربوبیت كا فیضان كیا ہے یہى كتاب كریم ہے، جس میں ہر وه چیز موجود ہے جو ان كے احوال كو درست اور ان كے اخلاق كى تكمیل كرتى ہے۔(السعدى: ۶۵۳)\nفرمان الٰہی (رب العالمين) میں ربوبیت كى صفت سے متصف كرنے كا كیا مقصد ہے؟\nتَنزِيلُ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ ٢\nسورت كى ابتداء شان قرآن کی عظمت و بلندی کے بیان سے ہوئی ہےاس لئے کہ قرآن تمام ہدایتوں کا جامع ہے جن کا بیان اس سورت میں اور دوسری سورتوں میں ہوا ہے،اور اس لئے بھى كہ گمراہوں كى گمراہى كى اصل جڑ اسى كتاب كو جھٹلانا ہے، پس الله نے قرآن كو لوگوں كیلئے ہدایت بنایا اور عرب کو یہ خصوصی شرف بخشا کہ ان کو اس کتاب کا پہلا استقبال کرنے والا بنایا (یعنی سب سے پہلے انہیں قبول کرنے کا موقع دیا)۔(ابن عاشور: ۲۱؍۲۰۵)\nآیت كریمہ شانِ قرآن کی عظمت پر دلالت كرتى ہے، اس كى وضاحت كریں.\nٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ مَا لَكُم مِّن دُونِهِۦ مِن وَلِيّٖ وَلَا شَفِيعٍۚ أَفَلَا تَتَذَكَّرُونَ ٤\nیعنی کیا تم ان نصیحتوں کو سنتے ہی نہیں ہو تاکہ نصیحت پکڑو، یا کیا تم انہیں سنتے ہو،مگر نصیحت حاصل نہیں کرتے، پہلے معنی میں نہ سننے اور نصیحت نہ حاصل کرنے دونوں پر نکیر ہے، اور دوسرے معنی میں نصیحت نہ حاصل کرنے پر نکیر ہے حالانکہ نصیحت حاصل کرنے کا سبب پایاجاتا ہے ، وہ سبب ہے نصیحتوں کا سننا۔(الألوسى: ۱۱؍۱۱۸)\nنصیحت كے سننے سے فائده كب ہوگا؟\nمَا لَكُم مِّن دُونِهِۦ مِن وَلِيّٖ وَلَا شَفِيعٍۚ أَفَلَا تَتَذَكَّرُونَ ٤\nالله تعالىٰ فرمار ہا ہے : لوگو! اگر وه تمہیں نقصان پہنچانا چاہے تو اس كے سوا كوئى تمہارا کارساز نہیں جو تمہارے معاملات کو سنبھال سکے اور تمہاری مدد کرسکے اور اگر وه تمہارى معصیت(نافرمانی) پر تمہیں عذاب دینا چاہے تو تمہارا كوئى سفارشی نہیں جو اس کے نزدیک تمہاری سفارش کرسکے، اس لئےصرف اسى كو اپنا كارسازسمجھو، اور اسى كى اطاعت كركے اپنے تمام معاملات میں اس سے مدد مانگو، كیونکہ وہ جب تمہاری حمایت و حفاظت کرنا چاہے گا تو وہ تمہاری حفاظت ہر اس شخص سے کرے گا جوتمہارے ساتھ براچاہتا ہے، اور تمہارے ساتھ جو اس کا ارادہ ہوگا تو اسے (اپنے ارادے سے) کوئی طاقت روک نہیں سکتی، کیونکہ کوئی غالب و زبردست اسےزیرنہیں کرسکتا ہے۔(الطبرى: ۲۰؍۱۶۶)\nدرست ہی نہیں ہے کہ دل اور اعضائے جسمانی اللہ کے علاوہ کسی اور سے تعلق استوار کرے، آیت كى روشنى میں اس كى وضاحت كریں.\nيُدَبِّرُ ٱلۡأَمۡرَ مِنَ ٱلسَّمَآءِ إِلَى ٱلۡأَرۡضِ ثُمَّ يَعۡرُجُ إِلَيۡهِ فِي يَوۡمٖ كَانَ مِقۡدَارُهُۥٓ أَلۡفَ سَنَةٖ مِّمَّا تَعُدُّونَ ٥\nاس آیت میں اس بات كى طرف اشاره ہے كہ بندے کی تدبیر تدبیرِ الٰہی کے سامنے بے اثر ہے، پس خوشخبرى ہے اس بندے کے لئےجسے الله كى تدبیر پر راضى ہونے کی توفیق مل گئی اور اپنى تدبیر سے بے نیاز ہوگیا۔(الألوسى: ۱۱؍۱۳۸)\nالله سبحانہ وتعالىٰ پر بھروسہ كرنے كا كیا فائده ہے؟\nذَٰلِكَ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡعَزِيزُ ٱلرَّحِيمُ ٦\nمذكوره باتوں كےبعد آخر میں الله تعالىٰ كو (العزيز الرحيم) كے صفات سے متصف كرنے كى مناسبت یہ ہے كہ الله تعالىٰ نے مخلوق كو محض اپنى قدرت كاملہ سے بغیر كسى سہارے كے پیدا كیا ہے، تو یہاں عزت کی صفت ظاہر ہے کیونکہ عزت الٰہی کا مطلب ہے دوسروں سے بالکل بے نیاز ہونا، اسی طرح اللہ نے مخلوقات کو ایسی حالتوں میں پیداکیا جن میں اللہ کا لطف و کرم ان کے ساتھ نمایاں ہے، پس وہ ان کو ان حالتوں میں پیداکرنے میں ان پر نہایت مہربان ہے، کیوں کہ ان کی زندگی کے معاملات کو ان کے لئے مناسب بنایا جس میں ان کے لئے نعمت ہے، اور ان کو تکلیفوں سے بچایا۔(ابن عاشور : ۲۱؍۲۱۵)\nآیت كریمہ میں الله تعالىٰ كے ساتھ (العزيز الرحيم) جیسے صفات لانے كى كیا مناسبت ہے؟\nwords\nافتَرَاهُاپني طرف سے گھڑ لايا.\nاستَوَىعلي و ارتفع /مستوي هوا ؛ جيسے اس كي شان كے لائق هے.\nيَعرُجُ إِلَيهِاس كي طرف چڑھتے هيں.\nنَسلَهُاس كي اولاد.\nسُلاَلَةٍنطفه ؛ كيونكه اسے تمام بدن سے كشيد كركے لايا گيا هوتا هے.\nمَهِينٍكمزور / باريك.\nضَلَلنَا فِي الأَرضِهم نے اس كو مرنے كے بعد مٹي كرديا."],[416,"§السجدہ\ndeeds\nاس آیت كے پڑھتےوقت سجدۂ تلاوت كیجئے.\nاپنا الارم سیٹ كردیں تاكہ رات میں اٹھ كر قیام اللیل کریں اور اپنے رب سے دعا کریں.\nكوئى صدقہ كریں.\nguid\nنیک کام کریں قبل اس كے كہ(وہ وقت آجائے جب) آپ انہیں كرنےکی تمناکریں گے، لیکن نہیں کرسکیں گے\nہدایت الله ہى كے ہاتھ میں ہے پس اسى سے ہدایت مانگئے.\nآپ کے پاس نیک عمل کا پوشیدہ ذخیرہ بھی ہونا چاہیے، لہٰذاكچھ ایسے نیك اعمال بھى کریں جنہیں الله كےعلاوه كوئى نہ جانے.\nrefl\nوَلَوۡ تَرَىٰٓ إِذِ ٱلۡمُجۡرِمُونَ نَاكِسُواْ رُءُوسِهِمۡ عِندَ رَبِّهِمۡ رَبَّنَآ أَبۡصَرۡنَا وَسَمِعۡنَا فَٱرۡجِعۡنَا نَعۡمَلۡ صَٰلِحًا إِنَّا مُوقِنُونَ ١٢\nاگر آپ آخرت میں مجرمین كا حال دیکھیں گے تو بڑا ہى ہولناك معاملہ پائیں گے، (ناكسوا رؤوسهم) (اپنا سر جھکائے ہوں گے)سر كا جھكانا یہ ذلت ، غم اور ندامت سے عبارت ہے، (ربنا أبصرنا وسمعنا) مطلب یہ ہے كہ وه كہیں گے: اے ہمارے رب! ہم سارى حقیقتوں سے آگاه ہوگئے۔(ابن جزى: ۲؍۱۷۸)\nقیامت كے دن مجرمین اپنے سروں كوكیوں جھكائے ہوئےہوں گے؟\nإِنَّمَا يُؤۡمِنُ بِـَٔايَٰتِنَا ٱلَّذِينَ إِذَا ذُكِّرُواْ بِهَا خَرُّواْۤ سُجَّدٗاۤ وَسَبَّحُواْ بِحَمۡدِ رَبِّهِمۡ وَهُمۡ لَا يَسۡتَكۡبِرُونَ۩ ١٥\nیعنى(مومن) الله سبحانہ وتعالىٰ کے لئے اپنے چہروں کے بل سجدے میں گرپڑتے ہیں، اسكى آیتوں كى تعظیم میں اور اسكى مضبوط گرفت وعذاب كے خوف سے۔(القرطبى: ۱۷؍۲۷)\nآیات الہى كے یاد دلانے كے وقت ایك مومن كى حالت كیسى ہونى چاہئے؟\nتَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ يَدۡعُونَ رَبَّهُمۡ خَوۡفٗا وَطَمَعٗا وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ١٦\n(تتجافى جنوبهم عن المضاجع) ان کےپہلو بستروں سے الگ ہوتےہیں، مطلب یہ ہے کہ نوافل (قیام اللیل) کثرت سے پڑھنے کی وجہ سے رات میں اپنے بستروں کو چھوڑ دیتے ہیں، اور جو عشاء اور فجر كى نماز جماعت سے پڑھ لے اس عظیم صفت میں اس کی بھی حصہ داری ہے۔(ابن جزى: ۲؍۱۷۹)\nبعض مومنوں نے اپنے بستروں كو (رات میں) چھوڑ ركھا ہے اس کا محرک کیا ہے؟\nتَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ يَدۡعُونَ رَبَّهُمۡ خَوۡفٗا وَطَمَعٗا وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ١٦\n(وطمعًا) یعنى(وہ اللہ کی عبادت میں شب بیداری کرتے ہیں) الله كى خوشنودى كى امید میں جو اجروثواب كا باعث ہے، اور یہاں لفظ(رجاء) کو چھوڑ کر (طَمَعًا) سے تعبیرکیاگیا، اس بات كى طرف اشاره كرنے كیلئے كہ وہ بندے اپنی کمیوں اور خامیوں کے شدید احساس کے سبب وہ اپنے اعمال كو كچھ بھى نہیں سمجھتے ہیں بلكہ وہ بغیر کسی سبب کے اللہ کے فضل کو طلب کرتے ہیں، اور جب یہ بندے بلا سبب الله كى رحمت كى امید کرتے ہیں، تو سبب كے ساتھ ان کی امید اور بڑھ جائے گی، اس طرح وه الله كى رحمت سے بالكل مایوس نہیں ہوں گے۔(البقاعى: ۱۵؍۲۵۶)\nرجاء كے بدلے طمع سے تعبیر كیوں كیا گیا؟\nتَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ يَدۡعُونَ رَبَّهُمۡ خَوۡفٗا وَطَمَعٗا وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ١٦\n(ومما رزقناهم ينفقون) جب الله تعالىٰ نے یہ ذکر کیا کہ (مومن بندے) اپنی جسمانی آرام و آسائش پر تقرب الی اللہ (عبادتِ الٰہی) کو ترجیح دیتے ہیں تو اس کے ساتھ یہ بھی ذکر کیا کہ یہ لوگ دیگر دنیاوی لذتوں کے ذریعۂحصول پر بھی تقرب الی اللہ کو ترجیح دیتے ہیں، اور وہ ذریعۂحصول ہے مال۔(ابن عاشور: ۲۱؍۲۲۹)\nقیام اللیل كےسلسلے میں گفتگو کے بعد (ومما رزقناهم ينفقون) كیوں لایا گیا ہے؟\nفَلَا تَعۡلَمُ نَفۡسٞ مَّآ أُخۡفِيَ لَهُم مِّن قُرَّةِ أَعۡيُنٖ\nیعنی اللہ تعالیٰ نے مومن بندوں کے لئے جنتوں میں ہمیشہ ہمیش رہنے والی ایسی نعمتوں کو چھپا رکھا ہے جن کی عظمتوں کو کوئی نہیں جانتا، اور ایسی لذتوں کو چھپارکھا ہے کہ ان جیسی لذتوں کا کسی کو پتہ تک نہیں، (کیونکہ) جب ان مومن بندوں نے اپنے اعمال كو چھپایا، تواسی طرح الله تعالىٰ نے ان کے ثواب كو بھى چھپادیا، اور یہى پورا پورا بدلہ ہے، کیونکہ بدلہ عمل كے جنس سے ہوتاہے۔ حسن بصرى رحمہ اللہ نے كہا: كچھ لوگوں نے اپنے اعمال كو چھپایا تو الله نے بهى انكے لئے ایسى نعمتوں كو چھپا ركھا ہے جسے نہ تو كسى آنكھ نے دیكھا ہے اور نہ ہى كسى فرد بشر كے دل میں اسكا خیال آیا ہے۔(ابن كثیر: ۳؍۴۴۳)\nاہل جنت کی جزا (بدلہ)کی بہت سارى چیزوں كو الله نے كیوں چھپا ركھا ہے؟\nكُلَّمَآ أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَآ أُعِيدُواْ فِيهَا\nعذاب كى انتہائى شدت كى وجہ سے جب كبھى وه نكلنے كا اراده كریں گےتوانہیں دوباره جہنم میں دھکیل دیا جائےگا، پس ان سے مصیبت دور ہونے کی خوشی ختم ہوجائے گی اور ان کی تکلیف سخت ہوجائےگی۔(السعدى: ۶۵۶)\nآیت كا یہ حصہ جہنمیوں كى شدت عذاب پر كیسے دلالت كرتاہے؟\nwords\nنَاكِسُوا رُؤُوسِهِمندامت سے سر جھكائے هوئے.\nحَقَّ القَولُثابت هوگيا۔ پورا گيا.\nالجِنَّةِجنات.\nتَتَجَافَىاٹھ جاتے هيں؛ عبادت كے ليے بيدار هوتے هيں.\nالمَضَاجِعِسونے كے ليے كمرے.\nمَا أُخفِيَ لَهُمجو ان كا بدله ذخيره كر ركھا هے.\nمِن قُرَّةِ أَعيُنٍجو فرحت بخشے / مسرور كرے.\nالمَأوَىٹھكانا ج/ ائے قيام.\nنُزُلًاضيافت."],[417,"§السجدہ\ndeeds\nتین ایسى مصیبتوں اور آزمائشوں كو یاد كریں جن سے الله تعالىٰ نے آپ كے شہر والوں كو ڈرایا ہو ، پھر انہیں دوسروں كو یاد دلائیں.\nكسى ایسى مصیبت كو یاد كریں جو آپ پر آئى ہو، پھر اپنے نفس كا محاسبہ كریں اور اپنے رب كى طرف رجوع اور توبہ كریں.\nقرآنى قصوں سے دنیوى عذاب کی ایسی پانچ شکلیں نکال كر پیش كریں جن سے نافرمانوں کو سزا دی گئی ہے.\nguid\nالله تعالىٰ نے پچھلى امتوں كو ہلاك كیا ہے، اس میں زندہ دل اورصاحب بصیرت كیلئے كافى نصیحت موجود ہے.\nعذاب مانگنے میں جلدی مچانا نادانی اور کم ظرفی کا پتہ دینا ہے.\nعذاب دیكھ لینے كےبعد، یا جان كنى كے وقت ملك الموت كو دیكھ لینے كے بعد توبہ قبول نہیں ہوتى.\nrefl\nوَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ ثُمَّ أَعۡرَضَ عَنۡهَآۚ إِنَّا مِنَ ٱلۡمُجۡرِمِينَ مُنتَقِمُونَ ٢٢\n(ومن أظلم) یعنى اپنى ذات كیلئےاس سے بڑھ کر ظالم کوئی نہیں، (ممن ذكر بآيات ربه) جسےرب کی آیتوں سے نصیحت کی گئی،یعنی ربانی دلائل اور نشانیوں سے، (ثم أعرض عنها) پھر اس نے ان سے منہ موڑلیا یعنی قبول نہیں کیا۔ (إنا من المجرمين منتقمون) ہم مجرموں سے بدلہ لیں گے ان كے جھٹلانے اور اعراض كرنے كى وجہ سے۔(القرطبى: ۱۷؍۴۰-۴۱)\nالله تعالیٰ كى نصیحتوں سے اعراض كرنےكى سنگینى اور اسكے انجام كو واضح كریں.\nوَجَعَلۡنَا مِنۡهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا لَمَّا صَبَرُواْۖ وَكَانُواْ بِـَٔايَٰتِنَا يُوقِنُونَ ٢٤\nاس آیت میں ان اوصاف كى طرف اشاره ہے جن سےایك مرشد كو متصف ہونا چاہئے، اور وه یہ ہیں: عبادات كى مشقتوں اور مختلف مصیتوں پر صبر كرنا، شہوات كى لذتوں سے نفس پر كنٹرول ركھنا،اور آیتوں پر یقین كرنا، پس جو مرشد ہونے کا دعویٰ کرے اور ان صفات سے متصف نہ ہو وه گمراه ہے۔(الألوسی: ۱۱؍۱۳۹)\nایك داعى ائمۂ ہدایت میں سے كب بن سكتاہے؟\nوَجَعَلۡنَا مِنۡهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا لَمَّا صَبَرُواْۖ\nسفیان ثورى سے على رضی اللہ عنہ كے اس قول كےبارےمیں سوال كیا گیا :ایمان میں صبر كا مقام ویسے ہى ہے جیسے جسم میں سر كا؟ تو انہوں نے كہا: كیا تم نے الله كایہ قول نہیں سنا: (وجعلنا منهم أئمة يهدون بأمرنا لمَّا صبروا) پھر فرمایا: جب انہوں نے چوٹی کے عمل (یعنی صبر) کو اختیار کیا تو وہ چوٹی کے سردار بن گئے۔(ابن كثیر: ۳؍۴۴۶)\nعلى بن ابى طالب رضی اللہ عنہ نے یہ معنی كہاں سے نكالا كہ ایمان میں صبر كا مقام ویسے ہى ہے جیسے جسم میں سر كا؟\nوَجَعَلۡنَا مِنۡهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا لَمَّا صَبَرُواْۖ وَكَانُواْ بِـَٔايَٰتِنَا يُوقِنُونَ ٢٤\n(لما صبروا) جب انہوں نے صبر كیا، یعنى انكے صبر كى وجہ سے ہم نے انہیں امام بنادیا، اور یہ صبر دین پر اور مصیتوں پر صبر كرنا ہے۔ اور كہاگیا: انہوں نے دنیا سے صبر كیا۔(القرطبى: ۱۷؍۴۳)\nاس آیت میں صبر سے كیا مقصود ہے؟\nأَوَ لَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّنَ ٱلۡقُرُونِ يَمۡشُونَ فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٍۚ أَفَلَا يَسۡمَعُونَ ٢٦\n(إن في ذلك) یعنى پچھلی سركش قوموں كى ہلاکتوں کا جوذكر كیا گیا،ان میں یا ان كے رہائش گاہوں میں، (لآيات) یعنى بڑى نشانیاں ہیں خود میں، اور تعداد میں بھى بہت زیاده ہیں۔ (أفلا يسمعون) كیا وه نہیں سن رہے ہیں، یعنى ان آیات كو غور و فکر کرنے کے لئے اور نصیحت حاصل کرنے کے لئے؟ (الألوسی: ۱۱؍۱۳۶)\nپچھلی امتوں كى خبروں كو بیان كرنے كا كیا فائده ہے؟\nقُلۡ يَوۡمَ ٱلۡفَتۡحِ لَا يَنفَعُ ٱلَّذِينَ كَفَرُوٓاْ إِيمَٰنُهُمۡ وَلَا هُمۡ يُنظَرُونَ ٢٩\nجس نے اس فتح سے مراد فتح مکہ سمجھا ہے وہ حقیقت سے بہت دور ہیں اور فاش غلطی پر ہیں؛ كیونكہ فتح مكہ كےدن رسول صلی اللہ علیہ وسلم نے قرشیوں كے اسلام كو قبول كیا تھا ، جن كى تعداد قریب قریب دو ہزار تھى، اگر اس آیت میں یہی فتح مکہ مراد ہوتی تو آپ(فتح مکہ کے دن) ان كے اسلام كو قبول نہیں كرتے، كیونكہ الله نے تو یہ فرمایا ہے: (قل يوم الفتح لا ينفع الذين كفروا إيمانهم ولا هم ينظرون)، چنانچہ یہاں فتح سے مراد حکم اور فیصلہ ہے۔ (ابن كثیر: ۳؍۴۴۷)\nاس آیت میں فتح سے كیا مقصود ہے؟\nفَأَعۡرِضۡ عَنۡهُمۡ وَٱنتَظِرۡ إِنَّهُم مُّنتَظِرُونَ ٣٠\n(اے نبی)آپ ان(جھٹلانے والے کافروں) كى بے وقوفیوں سے اعراض كریں اور انہیں صرف اتنا ہى جواب دیں جتنا آپ كو حكم كیا گیا ہے، (وانتظر إنهم منتظرون) یعنی فیصلے كے دن كا انتظار كریں، جس دن الله ان كے خلاف آپ كے حق میں فیصلہ كرےگا۔(القرطبى: ۱۷؍۴۶)\nجھٹلانےوالے اعراض كرنے والے مخالفین كےساتھ برتاؤ كے سلسلے میں قرآنى منہج واضح كیجئے.\nwords\nالعَذَابِ الأَدنَىدنياوي مصائب.\nمِريَةٍشك.\nمِن لِقَائِهِشب اسراء حضرت موسي كي ملاقات.\nالجُرُزِخشك/ سخت زمين جس ميں پيداوار نه هوتي هو.\nيُنظَرُونَوه مهلت ديے جاتے هيں."],[418,"§الأحزاب\ndeeds\nیہ دعا پڑھتےرہیں: (حَسْبِىَ اللّٰهُ لَا اِلٰهَ اِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْم) (میرے لئے اللہ کافی ہے، اس کے علاوہ کوئی معبود برحق نہیں صرف اسی پر میں نے بھروسہ کیا ہے وہ عظیم عرش کا رب ہے).\nامہات المومنین كیلئے رضا كى دعا(رضي اللّٰه عنهن) كریں اور ان كے حقوق كو سمجھیں.\nاپنے بعض رشتہ داروں كى زیارت كریں اور ا نكے ساتھ كسى بھى طرح کی كوئى صلہ رحمى كریں.\nguid\nالله تعالىٰ نے اپنے نبى كو تقوىٰ كا حكم دیا ہے تاكہ كوئى نصیحت و موعظت پر ناک نہ چڑھائے.\nكافر اورمنافق کسی بھی دینی معاملے میں مشوره لینے كے لائق نہیں ہیں.\nجو الله پر بھروسہ كرتاہے الله اسے ہر مصیبت سے نجات، ہر تنگى سے چھٹكارا اور ہر بلا سے عافیت میں ركھتاہے.\nrefl\nيَٰٓأَيُّهَا ٱلنَّبِيُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا ١\n(يا أيها النبي) اس خطاب میں آپ صلی اللہ علیہ وسلم كیلئے تكریم ہے، كیونكہ آپ كو نبوت كے خطاب سے پكارا گیا ہے، جبكہ دیگر تمام نبیوں كو ان كے نام كےساتھ پكارا گیا ہے۔(ابن جزى: ۲؍۱۸۱)\nاس آیت میں نبى كریم صلی اللہ علیہ وسلم كو پكارنا كیسے باعث تكریم ہے؟\nيَٰٓأَيُّهَا ٱلنَّبِيُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَۚ\nیہ اعلیٰ سے ادنیٰ پر تنبیہ ہے، كیونكہ الله تعالىٰ نے جب اس طرح کا حکم اپنے رسول اور اپنے بندے (محمد صلی اللہ علیہ وسلم) کو دیا ہے تو جو آپ سے نیچے(کمتر) ہیں انہیں اس حکم کی بجاآوری بدرجہ اولیٰ کرناچاہئے۔(ابن كثیر: ۳؍۴۴۸)\nتقوىٰ کا حكم اور كافروں اور منافقوں كى بات ماننے سے ممانعت ان دونوں سے كیا كوئى بے نیاز ہوسكتاہے؟\nوَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَۚ\nیہى(کفار و منافقین) حقیقى دشمن ہیں؛ لہذا ایسے كسى بھى معاملات میں ان كى بات نہ مانئے جو تقوىٰ كے مخالف ہو اور اس كیلئے توڑ ہو۔(السعدى: ۶۵۷)\nالله تعالىٰ نے كافروں اورمنافقوں كى بات ماننے سے منع كیوں كردیا؟\nوَٱتَّبِعۡ مَا يُوحَىٰٓ إِلَيۡكَ مِن رَّبِّكَۚ\nیعنی قرآن (کی پیروی کیجئے)، اس میں جاہلى رسم ورواج كى پیروى كرنے سے ڈانٹا گیا ہے، اور ان سے جہاد كرنے اور دینی بغض کی وجہ سے ان سے جدا رہنے کا حكم دیا گیا ہے، اور اس میں یہ بھى دلیل ہے كہ نص كى موجودگى میں آراء واقوال كو چھوڑ دیا جائےگا، یہ خطاب آپ صلی اللہ علیہ وسلم كیلئے اور آپ کی امت كیلئے بھی ہے۔(القرطبى: ۱۷؍۵۱)\nاس شخص پر كیسے رد كریں گے جو قرآن كو چھوڑ دیتاہے اور اپنى خواہشات اور دوسرے انسانوں كے اقوال کی پیروی کرتا ہے؟\nوَمَا جَعَلَ أَدۡعِيَآءَكُمۡ أَبۡنَآءَكُمۡۚ ذَٰلِكُمۡ قَوۡلُكُم بِأَفۡوَٰهِكُمۡۖ وَٱللَّهُ يَقُولُ ٱلۡحَقَّ وَهُوَ يَهۡدِي ٱلسَّبِيلَ ٤\nاَدْعِيَآءَ دعي کی جمع ہے، یہ اس لڑكے كو كہتےہیں جسے فلاں کا لڑکا کہہ کر پکارا جائےحالانکہ وه اسكا لڑكا نہیں ہے۔ اس آیت كا سبب نزول زید بن حارثہ رضی اللہ عنہ كا معاملہ ہے،اور وہ یہ ہے کہ آپ قبیلۂ كلب كے ایك نوجوان تھے، جنہیں بعض عرب نے قید كركے خدیجہ رضی اللہ عنہاكے ہاتھ بیچ دیا تھا، اور خدیجہ رضی اللہ عنہا نے انہیں نبى كریم صلی اللہ علیہ وسلم كو ہبہ كردیا، اور آپ نے انہیں اپنا لے پالك بیٹا بنا لیا، اس طرح انہیں زید بن محمد كہا جانے لگا، یہاں تك كہ یہ آیت نازل ہوئى۔(ابن جزى: ۲؍۱۸۲)\nاس آیت نے ایك جاہلى رسم کا خاتمہ کردیا، وہ رسم کون سی ہے؟\nٱلنَّبِيُّ أَوۡلَىٰ بِٱلۡمُؤۡمِنِينَ مِنۡ أَنفُسِهِمۡۖ\n(من أنفسهم) مومنوں پرآپ صلی اللہ علیہ وسلم كے فیصلےنافذ ہونے اور آپ کی اطاعت كے واجب ہونے میں باپ تو دور خود ان كى ذات سے بھى آپ زیادہ حقدار ہیں، كیونكہ آپ انہیں عقل وحكمت كى طرف ہى بلاتےہیں، اور انہیں ان ہی باتوں کاحکم دیتے ہیں جو ان کی نجات کا ذریعہ ہیں، جبكہ ان كا نفس انہیں خواہشات اور فتنوں كى طرف بلاتا ہے، سو وہ انہیں ان چیزوں کا حکم دیتا ہے جو ان کی ہلاکت کا ذریعہ ہیں۔۔(البقاعى: ۱۵؍۲۹)\nنبى كریم صلی اللہ علیہ وسلم ہماری ذات پر ہم سے زیادہ حقدار کیوں ہیں؟\nوَأَزۡوَٰجُهُۥٓ أُمَّهَٰتُهُمۡۗ\nالله تعالىٰ نے نبی کریم صلی اللہ علیہ وسلم کی بیویوں كو یہ شرف بخشا كہ انہیں امہات المومنین كا درجہ عطا کیا، یعنى ان کی تعظیم وتكریم اوران کے ساتھ حسن سلوك کرنا واجب ہے ، اور مردوں پر ان سے نکاح کرنا حرام ہے۔ (القرطبى: ۱۷؍۶۲)\nآیت كریمہ كى روشنى میں ان بدعتیوں اور بدعقیدوں پر رد كیسے كریں گے جو امہات المؤمنین كى شان میں گستاخى كرتےہیں؟\nwords\nتُظَاهِرُونَ مِنهُنَّظهار: كسي انسان كا اپني بيوي سے كهنا: تم مجھ پر ميري ماں كي پيٹھ جيسي هو.\nأَدعِيَاءَكُممنه بولا بيٹا/ جو اپني صلبي اولاد نه هو.\nوَمَوَالِيكُماور تمهارے ديني مددگار.\nجُنَاحٌگناه.\nأَولَى بِالمُؤمِنِينان كے ليے زياده نفع بخش ؛ رحيم ۔ اور دين و دنيا ميں ان كے زياده قريب و حق دار.\nوَأَزوَاجُهُ أُمَّهَاتُهُماس كي بيوي ان كي مائيں هيں؛ حقوق كي عظمت او رنكاح كي تحريم ميں."],[419,"§الأحزاب\ndeeds\nاولو العزم رسولوں كى سیرت پر غور کریں اور ان میں پائےجانے والے اہم مشتركہ صفات كو لکھیں.\nغزوہ احزاب كےبارےمیں پڑھیں تاكہ آپ کو معلوم ہو كہ كیسے الله تعالىٰ نے نبى كریم صلی اللہ علیہ وسلم اور صحابۂ كرام كو ثابت قدم ركھ كر ہمارے لئے دین اسلام كى حفاظت كى.\nنفاق اور اہل نفاق سے الله كى پناه مانگیں.\nguid\nغزوۂ خندق مسلمانوں كیلئے تکلیفوں اور مشقتوں سے پرسخت ترین غزوہ رہا ہے.\nالله تعالىٰ اپنے بندوں كو آزماتاہے تاكہ وه اپنے سچےبندوں كو جھوٹوں سے پہچان سكے.\nمنافق اپنے خالق كےساتھ اپنا عہد وپیمان نہیں نبھاتا تو مخلوق كےساتھ اسكا رویہ كیسا ہوسكتاہے.\nrefl\nوَإِذۡ أَخَذۡنَا مِنَ ٱلنَّبِيِّۧنَ مِيثَٰقَهُمۡ وَمِنكَ وَمِن نُّوحٖ وَإِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبۡنِ مَرۡيَمَۖ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظٗا ٧\nمذكوره پانچوں انبیاء(محمد، نوح، ابراہیم، موسیٰ، اور عیسیٰ علیہم السلام) گرچہ دیگر تمام انبیاء كے زمرے میں شامل ہیں لیكن یہاں انكا خصوصى ذكر کیاگیاہے ان کی فضیلت کو بیان کرنے کے لئے۔ اور كہاگیا: اس لئے(خصوصی ذکر کیاگیا) كہ وه پانچوں صاحب شریعت اور صاحب كتاب ہیں، اولو العزم رسول ہیں اور امتوں كے رہبر ہیں۔ (القرطبى: ۱۷؍۶۸)\nاس جگہ ان رسولوں كو بطور خاص كیوں ذكركیا گیا؟\nوَإِذۡ أَخَذۡنَا مِنَ ٱلنَّبِيِّۧنَ مِيثَٰقَهُمۡ وَمِنكَ وَمِن نُّوحٖ وَإِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبۡنِ مَرۡيَمَۖ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظٗا ٧ لِّيَسۡـَٔلَ ٱلصَّٰدِقِينَ عَن صِدۡقِهِمۡۚ وَأَعَدَّ لِلۡكَٰفِرِينَ عَذَابًا أَلِيمٗا ٨\nالله تبارك وتعالىٰ آگاه فرما رہاہے كہ اس نے تمام انبیاء كرام سے نہایت پختہ، باوزن اور موكد عہد وپیمان لیا ہے كہ وه الله كے دین پر اور اس كے راستے میں جہاد پر قائم رہیں گے۔ الله تبارك وتعالىٰ انبیائے كرام اور ان كے متبعین سے اس پختہ عہد كےبارے میں پوچھے گا كہ كیا انہوں نے اسے پورا كیا اور اس پر سچے اترے تاكہ انہیں نعمتوں بھرى جنت بطور ثواب عطا کرے؟ یا انہوں نے كفر كیا تاكہ انہیں دردناك عذاب دے؟ (السعدى: ۶۵۹)\nكیا پختہ عہدکے بارے میں (قیامت کے دن) پوچھ تاچھ صرف انبیاء ورسل كےساتھ خاص ہے؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَآءَتۡكُمۡ جُنُودٞ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا وَجُنُودٗا لَّمۡ تَرَوۡهَاۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا ٩\nیہ ہوا(غزوۂ خندق کے موقع سے) نبى كریم صلی اللہ علیہ وسلم كیلئے معجزه تھى؛ كیونكہ نبى كریم صلی اللہ علیہ وسلم اور صحابہ كرام اس سے بالكل قریب تھے ، ان كے اور طوفانی ہوا کےدرمیان صرف خندق کی چوڑائی تھی،(اس کے باوجود) وہ لوگ اس طوفانی ہوا سے عافیت میں تھے، اور اس كےبارےمیں انہیں كوئى خبربھی نہ تھى۔ (القرطبى : ۱۶؍۹۰)\nغزوۂ احزاب میں (اللہ نے) طوفانی ہوا بھیجی، اس میں معجزہ کی صورت کی وضاحت کریں.\nوَإِذۡ زَاغَتِ ٱلۡأَبۡصَٰرُ وَبَلَغَتِ ٱلۡقُلُوبُ ٱلۡحَنَاجِرَ\n(وإذ زاغت الأبصار)یعنى رعب کی وجہ سے آنکھیں جھکی اور کھلی کی کھلی رہ گئیں، اور كہا گیا: ہر چیز سے ہٹ ہوكر صرف دشمنوں کو دیکھتی رہ گئیں۔(وبلغت القلوب الحناجر) یعنى گھبراہٹ کی وجہ سے ان كے دل اپنى جگہ سے ہٹ گئے اور حلق تك پہنچ گئے۔(البغوى: ۳؍۵۴۴)\nوہ حالات جن سے مومنوں کو غزوہ احزاب کے وقت دوچار ہونا پڑا کس بات پر دلالت کرتے ہیں؟\nإِذۡ جَآءُوكُم مِّن فَوۡقِكُمۡ وَمِنۡ أَسۡفَلَ مِنكُمۡ وَإِذۡ زَاغَتِ ٱلۡأَبۡصَٰرُ وَبَلَغَتِ ٱلۡقُلُوبُ ٱلۡحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠ ١٠\n(وتظنون بالله الظنونا) یعنى تم گمان كرنے لگےتھے كہ كفار تمہارےاوپر غالب آجائیں گے، جبكہ الله تعالیٰ تمہیں ان پر غالب کرنے كا وعده كرچكا تھا، رہے منافقین تو انہوں نے برا سوچا اور اس كا اظہار بھى كیا، البتہ مومنوں كےدلوں میں بسا اوقات (بشرى تقاضوں كے مطابق) گرچہ کچھ اس طرح کا خیال گزرا جسے دور کرنا انسان کے بس میں نہیں ہوتا ہے لیكن انہوں نے عقلمندى كا ثبوت دیا اور الله كے وعدے پر یقین كیا۔ (ابن جزى: ۲؍۱۸۳)\nمومنوں اور منافقوں كے گمان میں كیا فرق ہے؟\nوَإِذۡ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورٗا ١٢\n(والذين في قلوبهم مرض ) کو (المنافقون) پر عطف کیا گیا ہے] اور عطف کے ظاہری اسلوب سے پتہ چلتا ہے کہ وہ لوگ(جن کے دلوں میں روگ تھا) منافقین نہیں تھے، اسى لئے كہا گیا: یہاں وه لوگ مراد ہیں جن کے دلوں میں منافقین نے شبہ ڈال کر اپنی طرف مائل کرلیاتھا۔ اور كہاگیا: یہاں وه كمزور عقیدے والے مراد ہیں جو نئے نئے مسلمان ہوئےتھے۔(الألوسی: ۱۱؍۱۵۶)\nاپنے شبہات كو پھیلانے كیلئے منافقین كس طرح كےلوگوں كو چنتےہیں؟\nوَإِذۡ قَالَت طَّآئِفَةٞ مِّنۡهُمۡ يَٰٓأَهۡلَ يَثۡرِبَ لَا مُقَامَ لَكُمۡ فَٱرۡجِعُواْۚ وَيَسۡتَـٔۡذِنُ فَرِيقٞ مِّنۡهُمُ ٱلنَّبِيَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوۡرَةٞ وَمَا هِيَ بِعَوۡرَةٍۖ إِن يُرِيدُونَ إِلَّا فِرَارٗا ١٣\n(طائفة منهم) یہاں بہت سارے ایسے لوگ مراد ہیں جن كےدل مریض ہیں بلكہ مرده ہوچكےہیں، جو ایک دوسرے کا چکر کاٹتے رہتے ہیں۔ (يا أهل يثرب) نبى كریم صلی اللہ علیہ وسلم نے جو نام (مدینہ ) اور (طیبہ) ركھا تھا ، ان بہترین ناموں كو چھوڑ كرقدیم نام (یثرب )كہا جبکہ اس نام کے قبیح ہونے کا احتمال ہے بایں طور کہ یہ (ثرب) سے ماخوذ ہے جو ملامت اور سرزنش كے معنى میں ہوتاہے، تاكہ دین اسلام سے بیزاری كا اظہار ہوسكے۔(البقاعى: ۱۵؍۳۰۶)\nنبى كریم صلی اللہ علیہ وسلم كے ذریعے ركھے گئے نام كو چھوڑ كرمدینہ کے قدیم نام كا استعمال كیوں كیا؟\nwords\nزَاغَتِ الأَبصَارُآنكھيں كھلي ره گئيں۔ حيرت او ردهشت كي وجه سے.\nغُرُورًاباطل / دھوكا.\nيَثرِبَمدينه طيبه كا جاهليت كا نام.\nلاَ مُقَامَ لَكُمشكست خورده جنگي معركه ميں جائے قيام.\nبُيُوتَنَا عَورَةٌهمارے گھر غير محفوظ هيں.\nأَقطَارِهَامدينه كي جوانب."],[420,"§الأحزاب\ndeeds\nدعا كریں الله تعالىٰ آپ كو تمام ڈھكے چھپے گمراه كن فتنوں سے محفوظ ركھے.\nآج اپنی استطاعت بھرالله تعالىٰ كى تسبیح وتكبیر اور حمد بیان كریں.\nچھوٹى ہوئى سنتوں میں كسى سنت كو زنده كریں.\nguid\nسختیوں اور آزمائشوں كى جگہوں سے بھاگنا نہ تو عمر میں اضافہ کرتا ہے اور نہ موت کو ٹالتا ہے، بلکہ یہ بسا اوقات غفلت کی حالت میں اس کی جلدی گرفت کا سبب ہوسکتا ہے.\nمنافقوں كى صفات میں سے ہے: لوگوں کو پسپائی پر آمادہ کرنا، اور خیر کے کاموں کو معطل کرنا، اس لئے اس بات سے بچیئے كہ آپ بھى خیر كو روكنے اور شر كو پھیلانے کا ذریعہ بنیں.\nنبی اکرم صلی اللہ علیہ وسلم کی اقتدا کے لئے سب سے زیادہ مددگار چیز آخرت کی یاد اور ذکرِ الٰہی ہے.\nrefl\nقُل لَّن يَنفَعَكُمُ ٱلۡفِرَارُ إِن فَرَرۡتُم مِّنَ ٱلۡمَوۡتِ أَوِ ٱلۡقَتۡلِ\nاسباب اس وقت فائده دیتےہیں جب قضاء وقدر(تقدیر) ان كى معارض نہ ہو، لیكن جب قضاء وقدر آجاتى ہے تو تمام اسباب ختم ہوجاتےہیں اور ہر وسیلہ بےکار ہوكر ره جاتاہے جن کو انسان ذریعۂ نجات سمجھتاتھا۔(السعدى: ۶۶۰)\nكیا آیت كےاندر اسباب كے ناکام ہونے پر كوئى دلیل ہے؟\nقُل لَّن يَنفَعَكُمُ ٱلۡفِرَارُ إِن فَرَرۡتُم مِّنَ ٱلۡمَوۡتِ أَوِ ٱلۡقَتۡلِ وَإِذٗا لَّا تُمَتَّعُونَ إِلَّا قَلِيلٗا ١٦\nآیت سے مقصود یہ ہے كہ مسلمان کے اندر یہ اخلاق (بدرجۂ اتم) پیدا کیاجائے کہ وہ دنیاوی زندگی کو حقیر سمجھیں، اور دینی تعلیمات کی اتباع کرکے اس درجۂکمال کی طرف بڑھنے میں اپنی پوری ہمت لگادیں جس میں ابدی سعادت ہے۔(ابن عاشور: ۲۱؍۲۹۱)\nآیت كےاندر ایك مسلمان كیلئے فانى دنیا پر باقی رہنے والی آخرت كو مقدم رکھنے كى تربیت موجود ہے ، اس كى وضاحت كریں.\n۞قَدۡ يَعۡلَمُ ٱللَّهُ ٱلۡمُعَوِّقِينَ مِنكُمۡ وَٱلۡقَآئِلِينَ لِإِخۡوَٰنِهِمۡ هَلُمَّ إِلَيۡنَاۖ وَلَا يَأۡتُونَ ٱلۡبَأۡسَ إِلَّا قَلِيلًا ١٨\nیعنى جو لوگوں كو جہاد سے روكتےہیں اور اپنے قول وعمل سے ركاوٹ بنتےہیں، (والقائلين لإخوانهم هلم إلينا) یہاں وه منافقین مراد ہیں جو جہاد میں نہ جاكر مدینہ میں بیٹھےتھے، اور اپنے قرابت داروں سے یا اپنے جیسے منافقین سے كہہ رہے تھے كہ آپ بھى جہاد چھوڑ كر ہمارے ساتھ آكر بیٹھ جائیں ۔ (ابن جزى: ۲؍۱۸۴)\nالله تعالىٰ نے اس آیت میں اور بعد كى آیتوں میں منافقوں كى ایك خاص صفت كا ذكر كیا ہے ، اسے بیان كرو.\nأَشِحَّةً عَلَيۡكُمۡۖ أَشِحَّةً عَلَى ٱلۡخَيۡرِۚ أُوْلَٰٓئِكَ لَمۡ يُؤۡمِنُواْ\n(أشحة عليكم) یعنى لڑائى كے وقت اپنے بدن كو استعمال كرنے میں اور جہاد میں اپنا مال خرچ كرنے میں بخیل ہیں۔ پس وه اپنے جان ومال كے ذریعے الله كے راستےمیں جہاد نہیں كرتے (أشحة على الخير) “یعنی ہر اس خیر میں بخیل ہیں جو ان سے مطلوب ہوتا ہے”۔ اور یہ انسان كا بدترین وصف ہے كہ اسے جو حكم دیاجائے اس كى تعمیل میں بخیل ہو۔اپنے مال کو اس کے صحیح راستے میں خرچ کرنے میں بخیل ہو۔ الله تعالىٰ كے دشمنوں كے خلاف جہاد كرنے اور الله كے راستے میں دعوت دینے میں اپنا بدن استعمال کرنے میں بخیل ہو، اپنے جاه(مقام و مرتبہ کے استعمال ) میں بخیل ہو اور اپنے علم، نصیحت اور رائے میں بخیل ہو۔ (السعدى : ۶۶۱)\nآیت میں مقصود بخالت كى قسمیں گناؤ؟\nفَإِذَا جَآءَ ٱلۡخَوۡفُ رَأَيۡتَهُمۡ يَنظُرُونَ إِلَيۡكَ تَدُورُ أَعۡيُنُهُمۡ كَٱلَّذِي يُغۡشَىٰ عَلَيۡهِ مِنَ ٱلۡمَوۡتِۖ\nان منافقین کے دیکھنے کی كیفیت كى تصویر كشى كى گئى ہے كہ وہ اس ڈرپوک دہشت زدہ کی طرح دیکھتے ہیں جو اپنی نگاہیں ٹکاکر ان سمتوں کی طرف دیکھتا رہتا ہے جن سے اسے مصیبت کے آنے کا اندیشہ رہتا ہے ۔ (ابن عاشور: ۲۱؍۲۹۷)\nآیت کریمہ كے اندر منافقوں كى ایك صفت كا بیان ہے جو خوفناک حالات كے وقت ظاہر ہوتى ہے، اسے ذکر كریں.\nلَّقَدۡ كَانَ لَكُمۡ فِي رَسُولِ ٱللَّهِ أُسۡوَةٌ حَسَنَةٞ لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَ وَذَكَرَ ٱللَّهَ كَثِيرٗا ٢١\nاس آیت كریمہ سے اہل اصول نے استدلال كیا ہےکہ رسول اللہ صلی اللہ علیہ وسلم کے افعال حجت (دلیل) ہیں، اور اصل قاعدہ یہ ہے کہ احکام میں آپ کی امت آپ کی اقتدا کرے گی سوائے ان احکام کے جن کے بارے میں شرعی دلیل اس بات پر دلالت کرتی ہے کہ وہ حکم آپ صلی اللہ علیہ وسلم کے ساتھ خاص ہے۔(السعدى: ۶۶۱)\nكیا رسول صلی اللہ علیہ وسلم كے افعال سے حجت پكڑ ا جاسكتاہے؟\nوَلَمَّا رَءَا ٱلۡمُؤۡمِنُونَ ٱلۡأَحۡزَابَ قَالُواْ هَٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥۚ وَمَا زَادَهُمۡ إِلَّآ إِيمَٰنٗا وَتَسۡلِيمٗا ٢٢\nیہ آیت دلیل ہے کہ لوگوں كے اعتبار سےاور ان کے حالات کے اعتبار سے ایمان میں مضبوطی اور اضافہ ہوتا ہے جیسا كہ جمہور ائمہ كا قول ہے كہ ایمان میں اضافہ اور كمى ہوتى رہتى ہے۔ (ابن كثیر: ۳؍۴۵۷)\nكیا ایمان گھٹتا بڑھتا ہے؟ اس آیت كى روشنى میں اس كى وضاحت كریں.\nwords\nالمُعَوِّقِينَجهاد سے پيچھے ره جانے والے.\nأَشِحَّةًاپنے مال اور جانوں كے بخيل.\nتَدُورُ أَعيُنُهُمان كي آنكھيں گھومتي هيں؛ خوف اور ڈر كي وجه سے.\nسَلَقُوكُمانهوں نے تم پر تهمت لگائي.\nحِدَادٍلمبي زبانيں / تكليف دينے والي زبان.\nبَادُونديهات ميں رهنے والے."],[421,"§الأحزاب\ndeeds\nصحابہ کی بعض سیرتوں كو (لوگوں کے سامنے) پیش کریں كہ وہى ہمارے پیشوا ہیں.\nاللہ کے دین پر ثبات قدمی اور اسكى اہمیت پر ایك پیغام بھیجیں.\nاللہ تعالیٰ سے دعا مانگیں کہ آپ کو (ہرموقف میں) سچائی سے نوازے، اور اس پر ثابت قدم رکھے یہاں تک کہ آپ اللہ سے جاملیں.\nguid\nصحابہ کے اعلیٰ مقام ومرتبہ اور ان کی فضیلت کا بیان ہے، اور اللہ کی طرف سے ان کا تزکیہ(پاکی اور نیکی کی گواہی) ہے، پس جس نے انہیں برا بھلا کہا تو گویا اس نے قرآن كى تكذیب كى.\nالله كى قدرت كى كوئى حد نہیں، وه ہر چیز پر قادر ہے، اسے كوئى چیز عاجز نہیں كرسكتى.\nاس بات كى وضاحت كہ عالم اور شریف انسان كى غلطى جاہل اور گھٹیا انسان كى غلطى سے کہیں زیاده سنگین ہوتى ہے.\nrefl\nمِّنَ ٱلۡمُؤۡمِنِينَ رِجَالٞ صَدَقُواْ مَا عَٰهَدُواْ ٱللَّهَ عَلَيۡهِۖ فَمِنۡهُم مَّن قَضَىٰ نَحۡبَهُۥ وَمِنۡهُم مَّن يَنتَظِرُۖ وَمَا بَدَّلُواْ تَبۡدِيلٗا ٢٣\n(وہ مومنین جنہوں نے اللہ کے ساتھ عہد وپیمان کو سچ کردکھایا) درحقیقت یہى لوگ جوانمرد ہیں ، ان كے سوا دیگر لوگوں كى صورتیں اگرچہ مردوں كى سى ہیں مگر ان كى صفات مردوں کی صفات ے کم تر ہیں۔(السعدى: ۶۶۱)\nحقیقى مردانگى كیا ہے؟\nوَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ إِن شَآءَ أَوۡ يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا ٢٤\n(منافقین کو ملنے والے) عذاب کو اللہ کی مشیت (چاہت) پر معلق کرنے میں منافقین کے لئے تنبیہ ہے کہ اللہ کی رحمت کشادہ ہے،اور وہ ان منافقین کی امید کو ختم نہیں کررہا ہے جنہوں نےجن گناہوں کا ارتکاب کیا ہے اس کی مغفرت کے لئے کوشش کریں بایں طور کہ (اللہ کی بارگاہ میں) توبہ کریں، پس اللہ تعالیٰ ان کی توبہ کو قبول کرےگا۔۔ (ابن عاشور: ۲۱؍۳۰۹)\nآیت كریمہ میں عذاب دینے كو مشیئت الٰہى پر معلق كیوں كردیا گیا ہے؟\nوَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ إِن شَآءَ أَوۡ يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا ٢٤\n(أو يتوب عليهم) یعنى اللہ تعالیٰ ان كو توبہ اور انابت(اللہ کی طرف رجوع کرنے) كى توفیق سے نوازے گا۔ اور اس كریم كى كرم نوازى پر یہى چیز غالب ہے ، اس لئے اس نے آیت كریمہ كو اپنے ان دو اسمائے حسنىٰ پر ختم كیا ہے جو اس كى مغفرت ، اسكے فضل و احسان پر دلالت كرتےہیں۔ (السعدى: ۶۶۲)\nغفور رحیم جیسے دو ناموں پر آیت كو ختم كیوں كیا؟\nوَكَفَى ٱللَّهُ ٱلۡمُؤۡمِنِينَ ٱلۡقِتَالَۚ وَكَانَ ٱللَّهُ قَوِيًّا عَزِيزٗا ٢٥\n(وكفى الله المؤمنين القتال) جنگ میں الله مومنوں كیلئے كافى ہوگیا كہ اس نے كافروں پر آندھى اور فرشتوں كى فوج بھیج دى ، یہاں تك كہ وه (کفار) لوٹ گئے اور بنو قریظہ كے لوگ بھى اپنے قلعوں میں لوٹ گئے، اس طرح بنو قریظہ پر رعب طارى كركے الله تعالىٰ مومنوں كیلئے كافى ہوگیا۔ (القرطبى: ۱۶؍۱۱۵)\nالله تعالىٰ كى قوت اور اسكى طاقت وغلبے كا اندازه اس سے لگایا جاسكتا ہے كہ اسكے پاس ایسى فوج ہے جسے اسكے سوا كوئى نہیں جانتا، آیت كى روشنى میں اس كى وضاحت كریں.\nوَأَوۡرَثَكُمۡ أَرۡضَهُمۡ وَدِيَٰرَهُمۡ وَأَمۡوَٰلَهُمۡ وَأَرۡضٗا لَّمۡ تَطَـُٔوهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٗا ٢٧\n(وأرضًا لم تطئوها) یہ ایسى سرزمین كى فتح كا وعده ہے جسے مسلمانوں نے اس وقت تک اپنے پاؤں سےنہیں روندا تھا، اور یہ مكہ ، یمن، شام، عراق اور مصر ہیں، اس طرح الله تعالىٰ مشرق سے مغرب تك مسلمانوں كو ان سارى زمینوں كا وارث بنا دیا۔(ابن جزى: ۲؍۱۸۶)\n(وأرضًا لم تطئوها) اس جملے میں وجہ اعجاز(معجزہ کی صورت) كیا ہے؟ اس كى وضاحت كریں.\nوَإِن كُنتُنَّ تُرِدۡنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلۡأٓخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلۡمُحۡسِنَٰتِ مِنكُنَّ أَجۡرًا عَظِيمٗا ٢٩\nازواج مطہرات كو جو اختیار دیا گیا ہے؛اس میں بہت سارے فوائد ہیں:جیسے كہ ازواج مطہرات كى رفعت اور ان کے رتبۂ بلند کا اظہار اور ان کے بلند ارادے کا بیان كہ انہوں نے دنیا اور اس کے سازوسامان كو چھوڑ كر الله تعالىٰ ، اس كے رسول اور آخرت كے گھر كو اپنا مطلوب ومقصود اور اپنى مراد بنایا۔ (السعدى: ۶۶۳)\nاس اختیار میں ازواج مطہرات کے بلند رتبے اور ارادےكا اظہار ہے، اس كى وضاحت كریں.\nيَٰنِسَآءَ ٱلنَّبِيِّ مَن يَأۡتِ مِنكُنَّ بِفَٰحِشَةٖ مُّبَيِّنَةٖ يُضَٰعَفۡ لَهَا ٱلۡعَذَابُ ضِعۡفَيۡنِۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا ٣٠\nجس چیزکی عظمت و حرمت جس قدر زیادہ ہوگی اگر اسے پامال کیاجائے گا تو سزائیں بھی بڑھ کر ملیں گی، اسی لئے آزاد آدمی کی حد غلام کے مقابلے میں اور شادی شدہ کی حد غیرشادی شدہ کے مقابلے میں بڑھی ہوئی ہے۔ (القرطبى: ۱۶؍۱۳۲)\nكیا جس كا مقام ومرتبہ بلند ہو اسكى غلطیوں كو بھى اسكے حق میں بڑھا دیا جاتا ہے؟\nwords\nقَضَى نَحبَهُنصرت دين كے ليے اپني نذر پوري كي؛ اور شهادت كي موت پائي.\nبِغَيظِهِم لَم يَنَالُوا خَيرًاغصه ميں بھرے۔ كه اپني مراد كو نه پاسكے.\nظَاهَرُوهُمان لشكروں كي مدد كي.\nصَيَاصِيهِمان كے قلعے.\nوَأُسَرِّحكُنَّتمهيں طلاق ديدوں.\nبِفَاحِشَةٍ مُبَيِّنَةٍكھلا هوا گناه / معصيت."],[422,"§الأحزاب\ndeeds\nاپنی بہنوں کو نصحیت کیجئے کہ غیر محرم مردوں سے مخاطب ہوتے وقت یا ان سے فون پر گفتگو كرتےوقت لچكیلى بات نہ کریں.\nایك پیغام بھیجئے جس میں عورتوں كو گھروں میں ٹھہرنے كى اہمیت بتائى گئى ہو بطور خاص اس زمانے میں.\nاس بات كى كوشش كیجئے كہ آپ اپنے گھر میں بھى كتاب الله اور سنت رسول صلی اللہ علیہ وسلم کو پابند ى كے ساتھ پڑھنے کا اہتمام كریں.\nguid\nعورتوں كى لچکیلی بات خطرناک ہے.\nبے پردگى حرام اور جاہلیت كى نشانى ہے.\nگھروں كے اندر قرآن كریم او ر دعائے ماثوره كے پڑھنے سے گھر انس وجن كے شیاطین كے شر وفساد سے محفوظ رہتےہیں.\nrefl\n۞وَمَن يَقۡنُتۡ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعۡمَلۡ صَٰلِحٗا نُّؤۡتِهَآ أَجۡرَهَا مَرَّتَيۡنِ وَأَعۡتَدۡنَا لَهَا رِزۡقٗا كَرِيمٗا ٣١\nاجر كو امہات المومنین كى ضمیر كى طرف اضافت كرنا اجر كے عظیم ہونے كى طرف اشاره ہے كہ وه ان کے مقام كےاعتبار سے مناسب ہے، نیز اسكے بلند مقام ہونے كى طرف بھى اشاره ہے كہ وه ایسے ہى اجر كى مستحق ہیں، اور اطاعت پر ان كے اجر كو بڑھانا در اصل ان كے مرتبے كى تعظیم و تکریم ہے۔ (ابن عاشور: ۲۲؍۵)\nآیت كریمہ كى روشنى میں ازواج مطہرات كے مقام ومرتبے كو واضح كریں.\nيَٰنِسَآءَ ٱلنَّبِيِّ لَسۡتُنَّ كَأَحَدٖ مِّنَ ٱلنِّسَآءِ إِنِ ٱتَّقَيۡتُنَّۚ\nالله تعالىٰ نے دوسرى عورتوں پر ازواج مطہرات كى فضیلت در اصل ان كے تقویٰ كى وجہ سے دى ہے، اور جب تقوى بدرجۂ اتم ان كے یہاں موجود تھا تو دیگر عورتوں پر ان كى فضیلت بھى پائى گئى، البتہ دیگر عورتوں کی عمومیت سے فاطمہ بنت رسول صلی اللہ علیہ وسلم ، مریم بنت عمران، اور آسیہ زوجۂ فرعون خارج ہیں ؛ كیونكہ رسول الله صلی اللہ علیہ وسلم نے ان میں سے ہر ایك كیلئے یہ گواہى دى ہے كہ یہ اپنے زمانے میں تمام عورتوں كى سردار رہى ہیں۔ (ابن جزى: ۲؍۱۸۸)\nدوسرى تمام عورتوں پر امہات المومنین كى فضیلت كى كیا شرط ہے؟ ان كے علاوه وه كون سى عورتیں ہیں جنہوں نے یہ فضیلت پائى ہے؟\nفَلَا تَخۡضَعۡنَ بِٱلۡقَوۡلِ فَيَطۡمَعَ ٱلَّذِي فِي قَلۡبِهِۦ مَرَضٞ وَقُلۡنَ قَوۡلٗا مَّعۡرُوفٗا ٣٢\nصحت مند دل میں كسى ایسى چیز كى شہوت نہیں ہوتى جس كو الله تعالىٰ نے حرام ٹھہرایا ہو۔ قلبِ صحیح کو صحت مند اور مرض سے سلامت ہونے كى وجہ سے اسباب گناه حرام شہوت كیلئے متحرك كر سكتےہیں نہ اسے اسكى طرف مائل كرسكتےہیں، بخلاف اس قلب كے جو مریض ہے، وه اس چیز كا متحمل نہیں ہوسكتا جس كا متحمل ایك صحت مند قلب ہوسكتاہے، وه اس چیز پر صبر نہیں كرسكتا جس پر ایك صحت مندقلب صبر كرسكتا ہے، لہذا اگر ایك ادنى سا سبب بھى اسے حرام كى طرف دعوت دے تو وه اس كى دعوت پر لبیك كہے گا اور اسكى نافرمانى نہیں كرےگا۔ (السعدى: ۶۶۴)\nیہاں بطور خاص قلب مریض كا ذكر كیوں كیاگیا؟\nوَقُلۡنَ قَوۡلٗا مَّعۡرُوفٗا ٣٢\nچونكہ انہیں نرم لہجے میں بات كرنے سے روك دیا گیا اس لئے یہ وہم لاحق ہو سكتا ہے كہ انہیں درشت كلامى كا حكم ہےچنانچہ اس وہم كو اس ارشاد كے ذریعے سے دور كیا گیا : (وقلن قولًا معروفًا) یعنى جس طرح دھیماپن اور نرم كلامى نہیں ہونى چاہئےاسى طرح درشت لہجے اور بد اخلاقى پر مشتمل كلام بھى نہیں ہونا چاہئے۔(السعدى: ۶۶۴)\nآیت كریمہ كو اس جملے (وقلن قولًا معروفًا) سے ختم كیوں كیا گیا؟\nوَقَرۡنَ فِي بُيُوتِكُنَّ\nام المؤمنین حضرت سوده رضی اللہ عنہ سے سوال كیا گیا: آپ باہر كیوں نہیں نكل رہى ہیں؟ تو آپ نے كہا: الله تعالىٰ نے ہمیں حكم دیا ہے كہ ہم اپنے گھروں میں ٹھہرےرہیں، اور ام المؤمنین حضرت عائشہ رضی اللہ عنہا جب اس آیت كى تلاوت كرتیں تو جنگ جمل كیلئے نكلنے پر خوب روتىں۔ (ابن جزى: ۲؍۱۸۸)\nاس آیت كریمہ پر امہات المومنین نے كیسے عمل كیا؟\nإِنَّمَا يُرِيدُ ٱللَّهُ لِيُذۡهِبَ عَنكُمُ ٱلرِّجۡسَ أَهۡلَ ٱلۡبَيۡتِ\nازواج مطہرات اہل بیت میں شامل ہیں ، اس پر یہ آیت صراحت كے ساتھ دلالت كر رہى ہے؛ كیونكہ اس آیت كا سبب نزول ازواج مطہرات ہى ہیں، اور بالاتفاق سبب حکم میں داخل ہوتا ہے ۔ (ابن كثیر: ۳؍۴۶۵)\nآیت كریمہ آل بیت كے تعلق سے كیسے شیعوں كے عقیدے كو باطل كر رہى ہے؟\nوَٱلصَّٰٓئِمِينَ وَٱلصَّٰٓئِمَٰتِ وَٱلۡحَٰفِظِينَ فُرُوجَهُمۡ وَٱلۡحَٰفِظَٰتِ\nچونکہ روزه ركهنا شہوت كو توڑنے میں بڑا معاون ہے اس لئے مناسب ہوا كہ اس كے بعد (والحافظين فروجهم والحافظات) كا ذكر كیا جائے۔ (ابن كثیر: ۳؍۴۶۹)\nروزے كے معاً بعد شرمگاہوں كى حفاظت كا ذكر كیوں كیا گیا ؟\nwords\nيَقنُت مِنكُنَّجو كوئي تم ميں الله اور رسول كي اطاعت كرے.\nوَأَعتَدنَاهم نے تيار كر ركھا هے.\nوَقَرنَسكون سے رهو.\nالرِّجسَتكليف / گندگي / برائي / گناه.\nوَالقَانِتِينَاطاعت گزار / الله كے سامنے جھكنے والے.\nوَالخَاشِعِينَالله تعاليٰ سے ڈرنے والے/ تواضع اختيار كرنے والے."],[423,"§الأحزاب\ndeeds\nكل سے زیادہ آج الله كا ذكر كریں.\nصبح وشام نبى كریم صلی اللہ علیہ وسلم پر درود پڑھتےرہیں تاكہ الله تعالىٰ آپ پر اپنی رحمتیں نازل کرتا رہے.\nكوئى علمى درس یا لیكچر تیار كریں تاكہ فرشتے آپ كیلئے رحمت ومغفرت كى دعا كریں.\nguid\nخواہشات نفس كے مطابق صریح احكام كى تاویل كرنے سے بچنا چاہئے اور شرعى احكام کو تسلیم کرنا اور ان كى فرمانبردارى کرنی چاہئے، اس لئے کہ یہ الله اور اسكے رسول صلی اللہ علیہ وسلم پر ایمان لانے كے لوازم میں سے ہے.\nجان لیں ! وعظ ونصیحت سے بلند كوئى فرد نہیں ہے.\nالله تعالىٰ اپنے اولیاء اور دین كى تبلیغ كرنے والوں كا دفاع كرتاہے.\nrefl\nوَمَا كَانَ لِمُؤۡمِنٖ وَلَا مُؤۡمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمۡرًا أَن يَكُونَ لَهُمُ ٱلۡخِيَرَةُ مِنۡ أَمۡرِهِمۡۗ\nمطلب یہ ہے كہ الله اور اسكے رسول كے(احکام کے) سامنے كسى بھى مومن مرد یا مومنہ عورت كو اختیار حاصل نہیں ، بلكہ سب پر یہ واجب ہے كہ الله اور اسكے رسول كے احكام وفرامین كے سامنے سر تسلیم خم كردیں۔ (ابن جزى: ۲؍۱۸۹)\nایك مومن پر كیا واجب ہے اس وقت جب كتاب وسنت سے دلیل مل جائے؟\nوَإِذۡ تَقُولُ لِلَّذِيٓ أَنۡعَمَ ٱللَّهُ عَلَيۡهِ وَأَنۡعَمۡتَ عَلَيۡهِ أَمۡسِكۡ عَلَيۡكَ زَوۡجَكَ وَٱتَّقِ ٱللَّهَ\nجو كوئى اپنى بیوى كو طلاق دینے كیلئے مشوره طلب كرتاہے اس كے لئے بہترین رائے یہ ہے كہ جہاں تك اصلاح احوال ممكن ہو اس كو اپنى بیوى كو طلاق نہ دینے كا مشوره دیا جائے كیونكہ بیوى كو اپنے پاس ركھنا طلاق دینے سے بہتر ہے۔(السعدى: ۶۶۶)\nاگر كوئى اپنى بیوى سے جدا ہونا چاہتا ہے تو اسے كس طرح كا مشوره دیا جائے؟\nوَتُخۡفِي فِي نَفۡسِكَ مَا ٱللَّهُ مُبۡدِيهِ وَتَخۡشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخۡشَىٰهُۖ\nرسول الله صلی اللہ علیہ وسلم كى طرف جو كچھ بھى وحى كیا گیا وه سب آپ نے پہونچا دیا اور كچھ بھى باقى نہیں ركھا حتى كہ وه حكم بھى پہونچا دیا جس میں آپ پر عتاب كیا گیا تھا۔ (السعدى: ۶۶۶)\nنبى كریم صلی اللہ علیہ وسلم نے پورى سچائى سے دین كى تبلیغ كر دى ہے ، آپ اس آیت سے كیسے استدلال كریں گے؟\nفَلَمَّا قَضَىٰ زَيۡدٞ مِّنۡهَا وَطَرٗا زَوَّجۡنَٰكَهَا لِكَيۡ لَا يَكُونَ عَلَى ٱلۡمُؤۡمِنِينَ حَرَجٞ فِيٓ أَزۡوَٰجِ أَدۡعِيَآئِهِمۡ إِذَا قَضَوۡاْ مِنۡهُنَّ وَطَرٗاۚ\nاس آیت سے ثابت ہوتا ہے كہ عملى تعلیم، قولى تعلیم سے زیاده بلیغ اور موثر ہے خاص طور پر جب عملى تعلیم قولى تعلیم سے مقرون اور متصل ہو تو پھر تو سونے پر سہاگہ ہے۔ (السعدى: ۶۶۶)\nآیت كےاندر عملی تطبیق کے ذریعہ تربیت کرنے كى طرف اشاره ہے ، اس كى وضاحت كریں.\nمَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٖ مِّن رِّجَالِكُمۡ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّۧنَۗ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٗا ٤٠\n(ولكن رسول الله) اس استدراك كے ذریعے اس وہم كو دور كردیا گیا ہے جو باپ كى نفى كردینے سے ہورہا تھا كہ اگر باپ نہ رہے تو پھرآپ كے اور امت كے مابین وه شفقت پدرى اور رحم وكرم كا جذبہ بھى نہ ہوگا جو ایك باپ اور بیٹے كے مابین پایا جاتاہے، اسى لئے انہیں یاد دلایا گیا كہ آپ صلی اللہ علیہ وسلم الله كے رسول ہیں اس حیثیت سے آپ امت كیلئے شفقت ورحمت میں اور امت كى طرف سے حسن سلوك اور عزت وتوقیر میں اپنى تمام امت كیلئے باپ ہى كے مانند ہیں، ہر اس نبى كى طرح جو اپنى امت كیلئےہوتا ہے۔ (ابن عاشور: ۲۲؍۴۴)\n(ولكن رسول الله)میں استدراك كا كیا فائده ہے؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرٗا كَثِيرٗا ٤١\nدوسرے تمام اعمال كے برخلاف ذكر واذكار كرنے میں الله تعالىٰ نے كثرت كى شرط لگائى ہے ، اور ذكر دل اور زبان دونوں سے ہوتاہے، اس كى بہت سارى صورتیں ہیں جیسے تہلیل، تسبیح، حمد، تكبیر، اور الله تعالىٰ كے اسماء حسنىٰ كا ذكر وغیره۔(ابن جزى: ۲؍۱۹۱)\nاس آیت كےاندر تمام افضل اعمال كو چھوڑ كر ذكر كیلئے كس خصوصیت كا بیان ہے؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرٗا كَثِيرٗا ٤١\nالله تعالىٰ نے اپنے بندوں كو حكم دیا كہ اسكا ذكركریں اور اسكا شكریہ ادا كریں، اورالله كى نعمت كو یاد کرکےكثرت سے ذکر و شکر كریں۔ الله تعالىٰ نے اسكى كوئى حد متعین نہیں كى كیونكہ یہ بندے پر بہت آسان ہے اور اس میں اجر بھى بہت عظیم ہے۔سیدنا ابن عباس رضی اللہ عنہ فرماتے ہیں: پاگل کے علاوہ کسی کے پاس اللہ کا ذکر چھوڑنے کا کوئی عذر نہیں ہے۔(القرطبى: ۱۶؍۱۶۷)\nالله تعالىٰ كے ذكر كو چھوڑنے كیلئے كیا كسى كیلئے عذر ہے؟\nwords\nقَضَىفيصله كيا/ حكم ديا.\nقَضَى زَيدٌ مِنهَا وَطَرًايعني زيد نے اسے طلاق ديدي.\nأَدعِيَائِهِمان كے منه بولے بيٹے.\nوَطَرًاضرورت / حاجت.\nحَرَجٍگناه."],[424,"§الأحزاب\ndeeds\nآپ اس سے بھى بڑى خاكسارى سے سلام كیجئے جو آپ سے عمر میں یا مقام ومرتبہ میں كم ہو ، ہوسكتا ہے یہى سبب بن جائے كہ كل قیامت كےدن الله آپ كو سلام پیش كرے.\nدعا كریں كہ الله تعالىٰ آپ كے اندر اخلاص پیدا كرے، اور آپ كى دعوت، اور امر بالمعروف اور نہى عن المنكر كوریاء سے بچائے.\nاپنے بھائیوں كو خوشخبرى دیجئے ان نعمتوں كى جو الله نے ان كیلئے تیار كر ركھا ہےاللہ کی عبادت اوراس کی بنائی ہوئی تقدیر پران كے صبر كرنے كى وجہ سے.\nguid\nنبى كریم صلی اللہ علیہ وسلم كا مقام ومرتبہ بہت اونچا ہے اور تمام مخلوق پر آپ صلی اللہ علیہ وسلم كى فضیلت بہت زیادہ ہے.\nدعوت دین اس وقت مشروع ہے جب داعى علم اور بردبارى كا حامل ہو.\nكافروں ، منافقوں ، فاجروں اور ظالموں كى اطاعت ان تمام چیزوں میں جو الله تعالىٰ كى مرضى كےخلاف ہوں؛ حرام ہے.\nrefl\nيَٰٓأَيُّهَا ٱلنَّبِيُّ إِنَّآ أَرۡسَلۡنَٰكَ شَٰهِدٗا وَمُبَشِّرٗا وَنَذِيرٗا ٤٥ وَدَاعِيًا إِلَى ٱللَّهِ بِإِذۡنِهِۦ وَسِرَاجٗا مُّنِيرٗا ٤٦\nیہ صفات گرامى جن سے الله تعالىٰ نے اپنے رسول محمد مصطفى صلی اللہ علیہ وسلم كو موصوف كیا ہے ، آپ كى رسالت كا مقصود ومطلوب اور اسكى بنیاد ہیں، جن سے آپ كو مختص كیا گیا ہے۔ (السعدى: ۶۶۷)\nہمارے نبى صلی اللہ علیہ وسلم كے وصف میں دوسرے صفات كو چھوڑ كر انہیں پانچ صفات كا ذكر بطور خاص كیوں كیا گیا؟\nيَٰٓأَيُّهَا ٱلنَّبِيُّ إِنَّآ أَرۡسَلۡنَٰكَ شَٰهِدٗا وَمُبَشِّرٗا وَنَذِيرٗا ٤٥\nڈرانےپر خوشخبرى دینے كو مقدم كیا گیا ہے ؛ كیونكہ نبى كریم صلی اللہ علیہ وسلم اكثر بشارت ہى دیتےتھے؛ اسلئے كہ آپ صلی اللہ علیہ وسلم رحمت للعالمین ہیں، اور چونكہ آپ كى امت میں مومنوں كى تعداد زیادہ ہوگی۔ (ابن عاشور: ۲۲؍۵۳)\nآیت كےاندر آپ صلی اللہ علیہ وسلم كى وصف میں ڈرانے پر خوشخبرى دینے كو مقدم كیوں كیا گیا؟\nوَدَاعِيًا إِلَى ٱللَّهِ\nدعوت الى الله اپنے نفس یا اس كى تعظیم كیلئے نہ ہو بلكہ خالص الله كےلئے ہو جیسا كہ اس مقام پر بہت سے نفوس كو كبھى كبھى یہ عارضہ لاحق ہوتا ہے۔ (السعدى: ۶۶۸)\nاخلاص كے تعلق سے بہت سارے دعاة سے لغزشیں ہوتی ہیں ، آیت كى روشنى میں اس كى وضاحت كریں.\nوَبَشِّرِ ٱلۡمُؤۡمِنِينَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضۡلٗا كَبِيرٗا ٤٧\nابن عطیہ رحمہ اللہ نے كہا: میرے والد نے مجھ سے كہا كہ الله كى كتاب میں یہ آیت میرے نزدیك سب سے زیاده امید دلانے والى ہے، كیونكہ الله تعالىٰ نے اپنے نبى كو حكم دیا ہے كہ آپ مومنوں كو خوشخبرى دے دیں كہ انكے لئے الله كے پاس بہت بڑا فضل ہے، اور اس بڑے فضل كى تفصیل الله تعالىٰ نے اس آیت میں بیان كى ہے، چنانچہ ارشاد بارى ہے:﴿وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فِي رَوۡضَاتِ ٱلۡجَنَّاتِۖ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِيرُ﴾[الشورى: ۲۲] (القرطبى: ۱۶؍۱۷۳)\nاس بات كى وضاحت كریں كہ بعض علماء نے اس آیت كو كیسے سب سے زیاده امید دلانے والى آیتوں میں شمار كیا ہے؟\nوَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَ وَدَعۡ أَذَىٰهُمۡ\nكیونكہ یہ چیز ان كو قبول اسلام كى طرف بلاتى ہے،اور آپ كو اور آپ كے گھر والوں كو بہت سى اذیتوں سے بچاتى ہے۔ (السعدى: ۶۶۸)\nالله تعالىٰ نے كافروں اور منافقوں كو اذیت دینے سے منع كیوں فرمایا؟\nوَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَ وَدَعۡ أَذَىٰهُمۡ\nیعنى وه لوگ آپ كو دین میں مداہنت كى جو دعوت دےرہےہیں ان كى بات كبھى مت ماننا اور نہ ہى كسى طور ان كا تعاون كرنا۔ (القرطبى: ۱۶؍۱۷۳)\nدعاة اور مبلغین سے كافر اور منافق كونسى ایك معین چیز چاہتےہیں؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نَكَحۡتُمُ ٱلۡمُؤۡمِنَٰتِ ثُمَّ طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمۡ عَلَيۡهِنَّ مِنۡ عِدَّةٖ تَعۡتَدُّونَهَاۖ فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحٗا جَمِيلٗا ٤٩\nالله تعالىٰ نے مردوں كو حكم دیا ہے كہ وه ایسى صورت میں بھى ان كو كچھ مال ومتاع دے دیں جو ان كى اس دل شكنى كا ازالہ كرے جو انہیں طلاق كى وجہ سے لاحق ہوئى ہے۔(السعدى: ۶۶۸)\nمطلقہ غیرمدخول بھا كو مال ومتاع دینے كى كیا حكمت ہے؟\nwords\nتَمَسُّوهُنَّتم ان سے مجامعت كرو.\nعِدَّةٍعورت كے ليے انتظار كي مدت.\nتَعتَدُّونَهَاتم ان كي عدت گزاري شمار كرتے هو .\nوَسَرِّحُوهُنّان كو طلاق ديدو.\nأَفَاءَ الله عَلَيكَجو آپ پر جهاد كي وجه سے انعام كيا.\nخَالِصَةً لَكَخاص هے آپ كے ساتھ."],[425,"§الأحزاب\ndeeds\nمرد و زن کے اختلاط میں تساہلی خطرناک ہے۔ اس موضوع پر تقریرکیجئے یا پیغام بھیجئے.\nدعا كریں كہ الله تعالىٰ آپ كو حق بات كہنےمیں جراءت ، حكمت اور حسن ادب سے نوازے.\nاپنے كسى ساتھى كو بتائیں كہ علماء اور دعاة كے ادب واحترام میں یہ بھى شامل ہے كہ انكى زیارت كے وقت انكے پاس دیر تك نہیں بیٹھنا چاہئے كہ اس سے ان كى مشغولیت زیادہ ہوتی ہے.\nguid\nیاد ركھیں الله تعالىٰ وه سب كچھ جانتا ہے جو آپ كے دل میں ہے، اس لئے دل میں وہى بات ركھیں جو الله كو راضى كرنے والى ہو.\nحق بات كہنے اور اسكى طرف بلانے میں شرم نہ کرنے کی عادت ڈالیں.\nغیر محرم عورتوں كےساتھ اختلاط سے بچیں؛ ہر وه ذریعہ جو مردوں كو عورتوں سے دور ركھے وہى طرفین كے دلوں كى پاكیزگى كا باعث ہے.\nrefl\nوَكَانَ ٱللَّهُ عَلِيمًا حَلِيمٗا ٥١\nصفت علم كى مناسبت تو الله تعالىٰ كے اس قول: (والله يعلم ما في قلوبكم) کی وجہ سے ظاہر ہے ، البتہ صفت حلیم كى مناسبت اس اعتبار سے ہے كہ یہاں رسول صلی اللہ علیہ وسلم كو یہ رغبت دلانا مقصود ہے كہ سب سے زیاده لائق اورمناسب حالت میں بھى حلم وبردبارى سے پیش آئیں۔ (ابن عاشور: ۲۲؍۷۷)\nآیت كریمہ كو صفت حلم پر ختم كرنے كى كیا حكمت ہے؟\nلَّا يَحِلُّ لَكَ ٱلنِّسَآءُ مِنۢ بَعۡدُ وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنۡ أَزۡوَٰجٖ وَلَوۡ أَعۡجَبَكَ حُسۡنُهُنَّ\nیہ الله تعالىٰ كى طرف سے اپنے رسول صلی اللہ علیہ وسلم كى ازواج مطہرات –رضى الله عنہن- كى قدر دانى ہے – اور الله تعالىٰ ہمیشہ سے اپنے بندوں كے اعمال كا قدردان ہے- كہ اس نے انكو اپنے سایۂ رحمت میں لے لیا اور رسول الله صلی اللہ علیہ وسلم كو انہیں پر اكتفا اور انحصار كرنے كا حكم دے دیا ؛ كیونكہ انہوں نے الله كے رسول اور آخرت كو چنا تھا۔ (السعدى: ۶۷۰)\nآیت كےاندر دنیا پر آخرت كو مقدم كرنے كى ترغیب ہے ، اسكى كیا وجہ ہے؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتَ ٱلنَّبِيِّ إِلَّآ أَن يُؤۡذَنَ لَكُمۡ إِلَىٰ طَعَامٍ غَيۡرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنۡ إِذَا دُعِيتُمۡ فَٱدۡخُلُواْ فَإِذَا طَعِمۡتُمۡ فَٱنتَشِرُواْ وَلَا مُسۡتَـٔۡنِسِينَ لِحَدِيثٍۚ إِنَّ ذَٰلِكُمۡ كَانَ يُؤۡذِي ٱلنَّبِيَّ فَيَسۡتَحۡيِۦ مِنكُمۡۖ\nابن عباس رضی اللہ عنہ نے فرمایا: یہ آیت ان لوگوں كےبارےمیں نازل ہوئى ہے جو نبى كریم صلی اللہ علیہ وسلم كے كھانے كا انتظار كررہے تھے اور كھانا كھلانے سے پہلے ہى آپ كے گھر پہنچ گئےتھے، پھر وہیں بیٹھے رہے یہاں تك كہ كھانا تیار ہوگیا، پھر كھا بھى لئے اور نہیں گئے، اسى لئے انہیں حكم دیا گیا كہ گھر میں داخل نہ ہوں یہاں تك كہ اجازت مل جائے، اور یہ كہ جب كھانا كھا لیں تو نكل جائیں جیسا كہ ارشاد ہے: (فإذا طعمتم فانتشروا) كہ كھانا كھالو تو واپس چلے جاؤ۔ بعض نے كہا: یہ الله كى طرف سے ادب ہے ان لوگوں كیلئے جو بوجھ بن كر بیٹھے رہتےہیں۔ (ابن جزى: ۲؍۱۹۴)\nوه كون سے آداب ِ زیارت ہیں جن كا پتہ اس آیت سے چلتاہے؟\nإِنَّ ذَٰلِكُمۡ كَانَ يُؤۡذِي ٱلنَّبِيَّ فَيَسۡتَحۡيِۦ مِنكُمۡۖ وَٱللَّهُ لَا يَسۡتَحۡيِۦ مِنَ ٱلۡحَقِّۚ\nشرعى معاملے میں اگر یہ وہم لاحق ہو كہ اس كے ترك كرنے میں ادب اور حیا ہے ، تو كامل حزم و احتیاط یہ ہے كہ شریعت كى پیروى كى جائے اور یہ یقین ركھا جائے كہ جو چیز شریعت كے خلاف ہے اس میں كوئى ادب نہیں۔ (السعدى: ۶۷۰)\nكیا لوگوں كا مطالبہ كرنا اپنے ان حقوق كا جنہیں شریعت نے ان كیلئے مستحق بنایا ہے ، ادب اور عام ذوق كے مخالف مانا جائےگا؟\nوَإِذَا سَأَلۡتُمُوهُنَّ مَتَٰعٗا فَسۡـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٖۚ ذَٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ\n(أطهر لقلوبكم وقلوبهن) یعنى عورتوں كے معاملے میں مردوں كے دلوں میں اور مردوں كے معاملے میں عورتوں كے دلوں میں جو شیطانى وسوسے پیدا ہوتےہیں ان كے لئے زیاده پاكیزگى كا سبب ہے؛ كیونكہ دیكھنا ہى تعلق بنانے اور فتنے كا سبب ہے، اور بعض آثار میں وارد ہوا ہے: نظر ابلیس كى زہر آلود تیروں میں سے ایك تیر ہے۔ (الألوسى: ۱۱؍۲۴۸)\nمرد وزن كا غیر محارم كو دیكھنے كا كیا اثر ہوتاہے؟\nوَإِذَا سَأَلۡتُمُوهُنَّ مَتَٰعٗا فَسۡـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٖۚ ذَٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ\nكیونكہ یہ طریقہ كسى قسم كے شبہے سے بعید تر ہے اور انسان شر كى طرف دعوت دینے والے اسباب سے جتنا دور رہے گا تو یہ چیز اس كے قلب كیلئے اتنى ہى زیاده سلامتى اور پاكیزگى كا باعث ہوگى۔ بنابریں الله تبارك وتعالىٰ نے جن شرعی امور كى كثرت سے تفاصیل بیان كى ہیں اور ان میں سے ایک چیز یہ بھی ہے كہ برائى كے تمام وسائل ، اسباب اور مقدمات ممنوع ہیں اور ہر طریقے سے ان سے دور رہنا مشروع ہے۔ (السعدى: ۶۷۰)\nشرعى حكمت میں یہ بھى ہے كہ صرف حرام كى حرمت پر اكتفا نہیں كیا جاتا بلكہ اسكے تمام اسباب اور ان راستوں كو بھى حرام كردیا جاتا ہے جو اس حرام تك پہونچانے والے ہوں، آیت كى روشنى میں اختصار كےساتھ اسكى وضاحت كریں.\nذَٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ\nفریقین كےدل تقوى، حرمات الہى كى تعظیم اور حرمت نبوى كى وجہ سے پاك ہیں، لیكن جب تقوى انہیں عصمت كے مرتبے تك نہ پہنچا سكا تو الله تعالىٰ نے چاہا كہ مومنوں كے اندر ایسے اخلاق اور صفات پیدا ہوجائیں جن سے شیطانى وسوسے سے محفوظ ہوكر الہى حفظ وامان میں آجائیں، چنانچہ شیطانى وسوسوں كے كمزور سے كمزور ترین وسیلوں كو بھى كاٹ دیا تاكہ امہات المؤمنین اس مقام اور عصمت کے قریب تك پہنچ سكیں جو انكے حق میں انكے شوہر كیلئے ثابت ہے؛ كیونكہ پاكیزه مردوں كیلئے پاكیزه عورتیں ہى خاص ہیں اور ایسا اس وقت ہوگا جب تمام شیطانى وسوسوں كو جڑ سے كاٹ دیا جائے گرچہ فرضى طور پر ہى كیوں نہ ہو۔ (ابن عاشور: ۲۲؍۹۱)\nدلوں كى پاكیزگى كیلئے سب سے بہتر وسیلے كیا ہیں؟\nwords\nتُرجِيآپ اس كو تقسيم رات ميں پيچھے كرديں.\nوَتُؤوِيآپ اپنے ساتھ ملائيں رات گزاري ميں.\nابتَغَيتَاس كے پاس رات گزارنا چاهيں.\nعَزَلتَاس كي تقسيم كو مؤخر كرديا.\nنَاظِرِينَ إِنَاهُكھانا تيار هونے كا انتظار.\nمَتَاعًاگھر كے برتنوں ميں سے كچھ."],[426,"§الأحزاب\ndeeds\nنبى كریم صلی اللہ علیہ وسلم پر خوب درود پڑھئے.\nمومن مردوں اور مومنہ عورتوں كیلئے استغفار كیجئے، خاص طور سے ان لوگوں كیلئے جنہیں آپكى زبان یا آپ كے كسى فعل سے كوئى تكلیف پہنچى ہو؛ كیونكہ انسان غلطیوں سے مبرا نہیں ہے.\nعورت كےپردے كے فوائد اور اسكے وجوب پر ایك پیغام لکھئے.\nguid\nشرعى پردے كى صفات میں سے یہ بھى ہے كہ یہ باپرده عورت كے ظاہرى علامات كو چھپا دیتا ہے یہاں تك كہ یہ بھى پتہ نہیں چلتا كہ وه كون ہے.\nیاد رکھیں كہ منافقوں كا انجام تباہى اور رحمتِ الہى سے دورى ہى ہے.\nالله تعالىٰ كى سنتیں دائمى ہیں ان میں كوئى تغیر اور تبدیلی نہیں ہوسكتى.\nrefl\nلَّا جُنَاحَ عَلَيۡهِنَّ فِيٓ ءَابَآئِهِنَّ وَلَآ أَبۡنَآئِهِنَّ وَلَآ إِخۡوَٰنِهِنَّ وَلَآ أَبۡنَآءِ إِخۡوَٰنِهِنَّ وَلَآ أَبۡنَآءِ أَخَوَٰتِهِنَّ وَلَا نِسَآئِهِنَّ وَلَا مَا مَلَكَتۡ أَيۡمَٰنُهُنَّۗ وَٱتَّقِينَ ٱللَّهَۚ\nیہاں خصوصى طور پر عورتوں كا ذكر كیا اور اس مسئلے میں انہیں كى تعیین كردى ؛ كیونكہ ان كے اندر اس مسئلے میں لا ابالى پن زیاده پائى جاتى ہے اور اسكا خیال بہت كم ہوتاہے، والله اعلم۔ (القرطبى: ۱۸؍۲۱۳)\nآیت كے آخر میں اس مسئلے كےاندر خصوصى طور پر عورتوں كو تقوى كى نصیحت كرنے میں كیا حكمت ہے؟\nإِنَّ ٱللَّهَ وَمَلَٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِيِّۚ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ صَلُّواْ عَلَيۡهِ وَسَلِّمُواْ تَسۡلِيمًا ٥٦\nالله كے بندے اور نبى جناب محمد صلی اللہ علیہ وسلم كا ملأ اعلى فرشتوں میں كیا مقام ومرتبہ ہے اس بارے میں الله تعالىٰ اپنے بندوں كو خبر دےرہاہے كہ الله تعالىٰ كس طرح آپ كى اپنے مقرب فرشتوں كے پاس تعریف كرتاہے، اور فرشتے آپ پر درود بھیجتےہیں، پھر الله تعالىٰ نے دنیا والوں كو حكم دیا كہ آپ پر درود وسلام بھیجیں؛ تاكہ عالم ملكوتى اور عالم دنیا دونوں كى تعریف آپ كیلئے اکٹھا ہوجائیں۔(ابن كثیر: ۳؍۴۸۷)\nالله تعالىٰ نے پہلے یہ خبر دى كہ نبى كریم صلی اللہ علیہ وسلم پر الله تعالىٰ اور فرشتے سلام بھیجتے ہیں، پھر آپ صلی اللہ علیہ وسلم پر درود وسلام بھیجنے كا حكم كیوں دیا؟\nإِنَّ ٱلَّذِينَ يُؤۡذُونَ ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَأَعَدَّ لَهُمۡ عَذَابٗا مُّهِينٗا ٥٧\nالله تعالىٰ كو تكلیف دینے كا مطلب یہ نہیں ہے كہ اسے كوئى تكلیف نقصان پہنچا سكتى ہے؛ كیونكہ الله تعالىٰ كو كوئى بھى چیز نہ تو نقصان پہنچا سكتى ہے اور نہ ہى نفع۔ اور كہاگیا: یہاں مضاف محذوف ہے، تقدیرى عبارت : (يُؤْذُوْنَ أَوْلِيَاءَ اللهِ) ہے،یعنی وہ اللہ کے اولیاء کو تکلیف پہنچا تے ہیں۔ جبكہ پہلى توجیہ راجح ہے؛ كیونكہ حدیث میں وارد ہے الله تعالىٰ فرماتاہے: ابن آدم مجھے گالى دیتاہے، جبكہ اس كیلئے مجھے گالى دینا مناسب نہیں، اوروه مجھے جھٹلاتاہے جبكہ اس كیلئے مجھے جھٹلانا مناسب نہیں، اسكا مجھے گالى دینا یہ ہے كہ وه كہتا ہے كہ میرے پاس بیوى بچےہیں، اور اسكا مجھے جھٹلانا یہ ہے كہ وه كہتاہے كہ میں اسے اسى طرح دوباره پیدا نہیں كرسكتا جیسا پہلى بار كیا۔(ابن جزى: ۲؍۱۹۶)\nالله تعالىٰ كو تكلیف كیسے دى جاتى ہے؟ اسكى وضاحت كریں.\nوَٱلَّذِينَ يُؤۡذُونَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ بِغَيۡرِ مَا ٱكۡتَسَبُواْ فَقَدِ ٱحۡتَمَلُواْ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا ٥٨\nمومنوں كى حرمت كو رسول صلی اللہ علیہ وسلم كى حرمت سے جوڑ دیا گیا ہے جس سے مومنوں كى شان ومرتبےكا پتہ چلتاہے، اور ان كا ذكر الگ سے كیا گیا جس میں اس بات كى طرف اشاره ہے كہ رسول صلی اللہ علیہ وسلم كا مقام سے انكا مقام كمتر ہے۔ اور یہ جملہ معترضہ ہے جسے نبى كریم صلی اللہ علیہ وسلم كى حرمت کے احکام اور ازواج مطہرات، آپ كى بیٹیوں اور مومنہ عورتوں سے متعلق آداب كے بیچ میں پیش كیا گیاہے۔(ابن عاشور: ۲۲؍۱۰۵)\nرسول صلی اللہ علیہ وسلم كى حرمت كےبعد مومنوں كى حرمت كا ذكر كیوں كیا گیا؟\nيَٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّأَزۡوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ ٱلۡمُؤۡمِنِينَ يُدۡنِينَ عَلَيۡهِنَّ مِن جَلَٰبِيبِهِنَّۚ\nالله تبارك وتعالىٰ نے اپنے نبى صلی اللہ علیہ وسلم كو حكم دیا كہ وه تمام عورتوں كو عمومى طور پر پردے كا حكم دیں ، اور اسكى ابتداء اپنى ازواج مطہرات اور اپنى بیٹیوں سے كریں كیونكہ كسى معاملے میں دوسروں كو حكم دینے والے كیلئے مناسب یہى ہے كہ وه دوسروں كے مقابلے پہلے اپنے گھر سے ابتداء كرے جیسا كہ ارشاد بارى ہے: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قُوٓاْ أَنفُسَكُمۡ وَأَهۡلِيكُمۡ نَارٗا﴾ [التحریم: ۶] یعنی اے ایمان والو! اپنے آپکو اور اپنے گھر والوں کو جہنم سے بچاؤ۔ (السعدى: ۶۷۲)\nدعوت كے میدان میں اس آیت سے داعى اور طالب علم كونسا فائده اٹھا سكتےہیں؟\n۞لَّئِن لَّمۡ يَنتَهِ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡمُرۡجِفُونَ فِي ٱلۡمَدِينَةِ لَنُغۡرِيَنَّكَ بِهِمۡ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلٗا ٦٠\nالله تبارك وتعالىٰ نے اس عمل كا ذكر نہیں فرمایا جس كےبارے میں ان كو تنبیہ كى گئى ہے كہ وه اس سے باز آجائیں تاكہ یہ اپنے عموم كے ساتھ ان تمام برائیوں سے رك جائیں جن پر انہیں ان كے نفس اكساتے، وسوسہ پیدا كرتے اور انہیں دعوت دیتےرہتےہیں، مثلا: اسلام اور اہل اسلام پر سب وشتم كرنا، مسلمانوں كےبارے میں برى افواہیں پھیلانا، ان كى قوتوں كو كمزور كرنے كى كوشش كرنا، مومن خواتین كےساتھ برائى اور فحش رویے سے پیش آنا اور دیگر گناه جو ان جیسے بدكردار لوگوں سے صادر ہوتےہیں۔(السعدى: ۶۷۲)\nافواه پھیلا نے والوں كے برى افواه کو نام کی تعیین کے ساتھ ذكر كیوں نہیں كیاگیا؟\n۞لَّئِن لَّمۡ يَنتَهِ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡمُرۡجِفُونَ فِي ٱلۡمَدِينَةِ لَنُغۡرِيَنَّكَ بِهِمۡ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلٗا ٦٠\nآیت كریمہ اس بات پر دلالت كرتى ہے كہ ان شرپسندوں كو ، جن كے مسلمانوں كےا ندر قیام سے مسلمانوں كو ضرر كا اندیشہ ہو، شہر بدر كیا جاسكتاہے، اس طریقے سے بہتر طور پر برائى كا سد باب ہوسكتاہے، اور برائى سے دور رہا جاسكتا ہے۔(السعدى: ۶۷۲)\nآیت كےاندر اس بات كى طرف رہنمائى كى گئى ہے كہ شرپسندوں سے دور رہاجائے اور انہیں اپنوں سے دور ركھا بھى جائے، اس كى وضاحت كریں.\nwords\nاحتَمَلُواانهوں نے اس كا ارتكاب كيا.\nبُهتَانًابهت برا اور فحش قسم كا جھوٹ.\nيُدنِينَ عَلَيهِنّگراديں اپنے سروں سے چهروں پر او رسينوں پر.\nوَالمُرجِفُونَجھوٹي خبريں پھيلانے والے.\nلَنُغرِيَنَّكَ بِهِمهم آپ پر مسلط كرديں گے."],[427,"§الأحزاب\ndeeds\nدعا کیجئے: (اَللّٰهُمَّ اصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ١ۖۗ اِنَّ عَذَابَهَا كَانَ غَرَامًا) یعنی اے اللہ! ہم سے جہنم کے عذاب کو پھیردینا۔ بلاشبہ اس کا عذاب لازم ہوجانے والا ہے.\nایك پیغام لكھ كریا مقالہ لكھ كر یا خطاب كےذریعے كسى ایسے نیك صالح شخص كا دفاع كیجئے جس پر جھوٹا بہتان لگایا گیا ہو.\nدعا کیجئے: (اَللّٰهُمَّ سَدِّدْلِسَانِىْ، وَاهْدِ قَلْبِىْ) اے اللہ!میری زبان کو پاکیزگی عطا فرما اور میرے دل کو ہدایت سے نواز دے.\nguid\nالله كى معصیت میں كسى سردار یا بزرگ كى بات نہ مانیں، كیونكہ یہ لوگ الله كے سامنے كچھ بھى كام نہیں آسكتے.\nالله كےبندوں كےساتھ حسن سلوك سے پیش آئیں اور كسى مسلمان كو تكلیف نہ دیں، بالخصوص علماء اور مصلحین كو.\nاس عظیم امانت كو یاد كریں جسے ابن آدم نے اٹھا ركھا ہے.\nrefl\nوَمَا يُدۡرِيكَ لَعَلَّ ٱلسَّاعَةَ تَكُونُ قَرِيبًا ٦٣ إِنَّ ٱللَّهَ لَعَنَ ٱلۡكَٰفِرِينَ وَأَعَدَّ لَهُمۡ سَعِيرًا ٦٤\nقیامت كى گھڑى كے مجرد قریب یا بعید ہونے میں كوئى فائده یا نتیجہ نہیں، حقیقى نتیجہ تو خساره یا نفع اور بدبختى یا خوش بختى ہے، نیز آیا بنده عذاب كا مستحق ہے یا ثواب كا؟ اور ان امور كے بارے میں تمہیں میں خبر دیتاہوں اور میں بتاتا ہوں كہ ان كا مستحق كون ہے؟ لہذا اللہ سبحانہ و تعالیٰ نے عذاب كے مستحق لوگوں كا وصف بیان كیا اور اس عذاب كا وصف بیان كیا جس میں ان كو مبتلا كیا جائے گا كیونكہ یہ وصف مذكور قیامت كى تكذیب كرنے والوں پر منطبق ہوتاہے، ارشاد بارى ہے: (إن الله لعن الكافرين) (السعدى: ۶۷۲)\nقرب قیامت كے ذكر كےبعد كافروں كے عذاب كے ذكر كرنے میں كیا حكمت ہے؟\nيَوۡمَ تُقَلَّبُ وُجُوهُهُمۡ فِي ٱلنَّارِ يَقُولُونَ يَٰلَيۡتَنَآ أَطَعۡنَا ٱللَّهَ وَأَطَعۡنَا ٱلرَّسُولَا۠ ٦٦\nتمام اعضاء جسم میں خصوصى طور پر چہروں كا ذكركیا گیا ہے؛ كیونكہ جلد كے دوسرے حصوں كے بالمقابل آگ كى تپش چہروں كو زیاده تكلیف دیتى ہے، اس لئے كہ چہرے بہت ہى نرم اعضاء حساسہ جیسے آنكھ، منہ، كان اور ناك کاٹھكانہ ہیں، ، جیسا كہ ارشاد بارى ہے: ﴿أَفَمَن يَتَّقِي بِوَجۡهِهِۦ سُوٓءَ ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِ﴾ [الزمر: ۲۴] بھلا جو شخص قیامت کے دن بدترین عذاب کی ڈھال منہ کو بنائے گا۔ (ابن عاشور: ۲۲؍۱۱۶)\nتمام آیت كریمہ میں بطور خاص صرف چہروں كا ذكر كیوں كیا گیا؟\nفَبَرَّأَهُ ٱللَّهُ مِمَّا قَالُواْۚ وَكَانَ عِندَ ٱللَّهِ وَجِيهٗا ٦٩\nابن عباس رضی اللہ عنہ نے كہا: موسیٰ علیہ السلام الله كے نزدیك بہت ہى مقبول تھے كچھ بھى مانگتے الله ضرور دیتا۔ اور حسن رحمہ اللہ نے كہا: آپ مستجاب الدعوه تھے، اور كہاگیا: آپ ہر دل عزیز اور مقبول تھے۔ (البغوى: ۳؍۵۸۸)\nموسىٰ علیہ السلام كا اپنےرب كے نزدیك كیا مقام ہے ، اس كى وضاحت كیجئے.\nوَقُولُواْ قَوۡلٗا سَدِيدٗا ٧٠ يُصۡلِحۡ لَكُمۡ أَعۡمَٰلَكُمۡ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ فَازَ فَوۡزًا عَظِيمًا ٧١\n(وقولوا قولًا سديدًا) ابن عباس رضی اللہ عنہ نے كہا: یعنى درست بات كہو۔ اور قتاده رحمہ اللہ نے كہا: انصاف والى بات كہو۔ اور حسن رحمہ اللہ نے كہا: سچى بات كہو۔(يصلح لكم أعمالكم) ابن عباس رضی اللہ عنہ نے كہا: یعنى تمہارى نیكیوں كو قبول كرےگا۔ اور مقاتل رحمہ اللہ نے كہا: تمہارے اعمال كا تزكیہ كرےگا۔ (ويغفرلكم ذنوبكم ومن يطع الله ورسوله فقد فاز فوزًا عظيمًا) یعنى ہر بھلائی پانے میں كامیاب ہوگا۔(البغوى: ۳؍۵۸۹)\nزبان كى حفاظت اور درست بات كہنے کے بہتر نتائج كیا ہیں؟\nإِنَّا عَرَضۡنَا ٱلۡأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلۡجِبَالِ فَأَبَيۡنَ أَن يَحۡمِلۡنَهَا وَأَشۡفَقۡنَ مِنۡهَا وَحَمَلَهَا ٱلۡإِنسَٰنُۖ إِنَّهُۥ كَانَ ظَلُومٗا جَهُولٗا ٧٢\nامانت سے مراد شرعى تكالیف ہیں جیسے اطاعت كو لازم پكڑنا اور برائیوں كو چھوڑدینا، اور كہاگیا: اس سے مراد مال كى امانت ہے، اور كہاگیا: اس سے مراد غسل جنابت ہے، صحیح بات یہ ہے كہ اس سے مراد تمام شرعى تكالیف ہیں۔ (ابن جزى: ۲؍۱۹۸)\nیہ كون سى امانت ہے جس كا بوجھ الله تعالىٰ نے ہمارےاوپر ڈالا ہے؟\nإِنَّا عَرَضۡنَا ٱلۡأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلۡجِبَالِ فَأَبَيۡنَ أَن يَحۡمِلۡنَهَا وَأَشۡفَقۡنَ مِنۡهَا وَحَمَلَهَا ٱلۡإِنسَٰنُۖ إِنَّهُۥ كَانَ ظَلُومٗا جَهُولٗا ٧٢\nزمین پر پہاڑ كو عطف كیا گیا جبكہ وه اسى كا حصہ ہے؛ كیونكہ پہاڑ زمین كےظاہرى اجزاء میں سے ایك بڑا حصہ ہے، جس کی عظمت کا مشاہدہ آنکھوں سے کیاجاتا ہے۔(ابن عاشور: ۲۲؍۱۲۵)\nزمین پر پہاڑ كو عطف كیوں كیاگیا جبكہ وه اسى كا حصہ ہے؟\nإِنَّا عَرَضۡنَا ٱلۡأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلۡجِبَالِ فَأَبَيۡنَ أَن يَحۡمِلۡنَهَا وَأَشۡفَقۡنَ مِنۡهَا وَحَمَلَهَا ٱلۡإِنسَٰنُۖ إِنَّهُۥ كَانَ ظَلُومٗا جَهُولٗا ٧٢ لِّيُعَذِّبَ ٱللَّهُ ٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡمُشۡرِكِينَ وَٱلۡمُشۡرِكَٰتِ وَيَتُوبَ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمَۢا ٧٣\nالله تعالىٰ اس امانت كى عظمت بیان كررہاہے جو اس نے مكلفین كےسپرد كى۔ لوگ اس امانت كو قائم ركھنے اور قائم نہ ركھنے كے لحاظ سے تین اقسام میں منقسم ہیں: منافقین: جو ظاہرى طور پر اس امانت كو قائم ركھتےہیں اور باطن میں اس كو ضائع كرتےہیں۔ مشركین: جنہوں نے ظاہرى اور باطنى دونوں طور پر اس امانت كو ضائع كردیا ہے۔ مومنین : جنہوں نے ظاہرى اور باطنى ہر لحاظ سے اس امانت كو قائم كر ركھا ہے۔ الله تبارك وتعالىٰ نے ان تینوں اقسام كے لوگوں كے اعمال اور ان كے ثواب وعقاب كا ذكر كرتےہوئے فرمایا: (ليعذب الله المنافقين والمنافقات والمشركين والمشركات ويتوب الله على المؤمنين والمؤمنات وكان الله غفورًا رحيمًا) (السعدى: ۶۷۴)\nامانت كے تعلق سے لوگوں كى كتنى قسمیں ہیں؟\nwords\nسَعِيرًابھڑكتي هوئي آگ.\nضِعفَينِدو گنا.\nوَجِيهًاعظيم القدر.\nسَدِيدًاحق كے موافق ۔ جھوٹ او رباطل سے پاك.\nفَأَبَينَانهوں نے انكار كرديا.\nوَأَشفَقنَوه ڈر گئے (خيانت هو جانے سے)."],[428,"§سبإ\ndeeds\nدعا کیجئے: “اَللّٰهُمَّ جَازِنِيْ بِالْحَسَنَاتِ إِحْسَانًا، وَبِالسَّيِّئَاتِ عَفْوًا وَغُفْرَانًا”: اے اللہ! مجھے اچھائیوں اور نیکیوں کا احسان کے ساتھ بدلہ دینااور برائیوں کے بدلہ میں مغفرت و معافی عطافرمانا.\nآج كوئى نیا صالح عمل كریں، اس امید میں كہ الله آپ كى مغفرت كرے اور اچھى رزق سے نوازے.\nكوئى علمى درس تیار كریں تاكہ باطل سے حق كى معرفت ہوسكے.\nguid\nجو دنیا میں الله تعالىٰ كى حمد وثنا زیاده كرتاہے وه اس لائق ہے كہ آخرت میں ان لوگوں میں سے ہو جو اس كى حمد وثنا وہاں كریں گے.\nان لوگوں میں سے بنئے جو الله تبارك وتعالىٰ كے دین كى طرف بلاتےہیں اور اسكا دفاع كرتےہیں، اور ان لوگوں سے دور رہئے جو لوگوں كو دین حق سے روكتےہیں.\nصحیح شرعى علم جو فرمان الٰہى اور سنت نبوى کی اتباع پر مبنى ہو دنیا وآخرت كى كامیابى كا ضامن ہے.\nrefl\nٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ\nسورت كو (الحمد لله) سے شروع كیا گیا اس بات كى طرف اشاره كرنے كیلئے كہ یہ سورت ایسے دلائل پر مشتمل ہے جن سے الله كى وحدانیت اور ان عظیم صفات كا پتہ چلتاہے جو اسكے لئے حمد وثنا كا تقاضہ كرتےہیں اور اسكے ساتھ حمد كى خصوصیت كا پتہ دیتےہیں۔(ابن عاشور: ۲۲؍۱۳۵)\nسورۂ سبا كو (الحمد لله)كےذریعے شروع كرنے كى كیا مناسبت ہے؟\nٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ\nاس صلے سے در اصل اشاره ہے مشركین كى اس ناشكر ى كى طرف جو ایسى چیزوں كى حمد وثنا كرتےہیں جن كی اس تمام عالم میں ادنى تاثیر بھى نہیں، اور نہ ہى ان کے محتوی کا انہیں کوئی شعورہے، جبكہ وه بھول بیٹھے ہیں اس ذات كى حمد وثنا کو جو ان سب كا مالك ہے اور ان تمام چیزوں كا مالك ہے جو آسمان وزمین كےاندر موجود ہیں۔(ابن عاشور: ۲۲؍۱۳۶)\nآیت كریمہ میں موصول كے اس صلہ كا كیا فائده ہے؟\nوَلَهُ ٱلۡحَمۡدُ فِي ٱلۡأٓخِرَةِۚ\nاس لئے كہ آخرت میں اس كى حمد وثنا اس طرح سے ظاہر ہوگى جس طرح دنیا میں نہیں تھى ، اور جب الله تعالىٰ تمام مخلوق كے درمیان فیصلہ كرےگا، اور تمام مخلوق اسكے فیصلے، اسكے كامل عدل وانصاف، اور اس میں اسكى حكمت كو دیکھیں گے تو وه سب اس پر اسكى حمد وثنا بیان كریں كے حتىٰ كہ ان جہنمیوں كے دل بھى ، جن كو عذاب دیا جائےگا، الله تعالىٰ كى حمد سے لبریز ہوں گے، نیز ان كو اعتراف ہوگا كہ یہ عذاب ان كے اعمال كى جزا ہے اور الله تعالىٰ ان كو عذاب دینے كے فیصلے میں عادل ہے۔ (السعدى: ۶۷۴)\nالله تعالىٰ كى حمد وثنا كو آخرت میں خاص كیوں كیاگیا؟\nعَٰلِمِ ٱلۡغَيۡبِۖ لَا يَعۡزُبُ عَنۡهُ مِثۡقَالُ ذَرَّةٖ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِ وَلَآ أَصۡغَرُ مِن ذَٰلِكَ وَلَآ أَكۡبَرُ إِلَّا فِي كِتَٰبٖ مُّبِينٖ ٣\n(لا يعزب عنه) كوئى چیز اس سے اوجھل نہیں، یعنى ہر چیز اس كے علم میں ہے، كوئى چیز اس سے مخفى نہیں ہے، پس ہڈیاں گرچہ سڑ گل كر ریزه ریزه ہوجائیں وه انہیں بھى جانتاہے كہ كہاں جاکر بكھرى ہوئى ہیں ، پھر انہیں اكٹھا كردے گا اسى طرح جیسے پہلى بار انہیں بنایا تھا ، بیشك وه ہر چیز كو جاننےوالا ہے۔(ابن كثیر: ۳؍۵۰۴)\nبعث ونشور كے بعد الله تعالىٰ كیلئے عالم الغیب ہونے كى صفت كا ذكر كیوں كیاگیا؟\nوَيَرَى ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ ٱلَّذِيٓ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ هُوَ ٱلۡحَقَّ\n(وَيَعْلَمُ) فعل چھوڑ كر(وَ يَرَى) فعل رؤیت كو اختیار كیا گیا اس بات كى طرف اشاره كرنے كیلئے كہ یہ علم یقینى ہے اسى طرح سے جیسے مشاہدات والى چیزوں كے بارےمیں علم ضرورى ہوتاہے۔(ابن عاشور: ۲۲؍۱۴۵)\nآیت كریمہ كےاندر (وَيَعْلَمُ) فعل كوچھوڑ كر (وَ يَرَى) كو كیوں اختیار كیاگیا ہے؟\nوَيَرَى ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ ٱلَّذِيٓ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ هُوَ ٱلۡحَقَّ وَيَهۡدِيٓ إِلَىٰ صِرَٰطِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ ٦\nتمام اسمائے حسنىٰ میں سے صرف انہیں دونوں صفت (العزيز الحميد) كو ترجیح دینے سے اس بات كى طرف اشاره ہے كہ مومن جب یہ ایمان لاتےہیں كہ قرآن ہى حق اور ہدایت ہے تو اس ایمان سے انہیں یہ احساس ہوتاہے كہ یہى وه راستہ ہے جو انہیں غلبہ اور عزت كى طرف لےجانےوالا ہے ، ارشاد بارى ہے: ﴿لِلَّهِ ٱلۡعِزَّةُ وَلِرَسُولِهِۦ وَلِلۡمُؤۡمِنِينَ﴾ [المنافقون: ۴۸]عزت و غلبہ اللہ کے لئے ہے، اس کے رسول کے لئے ہے اور مومنوں کے لئے ہے۔(ابن عاشور: ۲۲؍۱۴۶)\nآیت كریمہ میں دونوں صفت: (العزيز الحميد) كے ترجیح دینے كا كیا فائده ہے؟\nوَقَالَ ٱلَّذِينَ كَفَرُواْ هَلۡ نَدُلُّكُمۡ عَلَىٰ رَجُلٖ يُنَبِّئُكُمۡ إِذَا مُزِّقۡتُمۡ كُلَّ مُمَزَّقٍ إِنَّكُمۡ لَفِي خَلۡقٖ جَدِيدٍ ٧\nاگر آپ یہ اعتراض كریں كہ رسول صلی اللہ علیہ وسلم قریش كےاندر ایك معروف شخصیت تھے اور قیامت كے بارے میں آپ كا انہیں خبر دینا ایك معروف بات تھى، پھر یہاں ان كا یہ كہنا كیا معنى ركھتا ہے كہ : (هل ندلكم على رجل) (كیا ہم تمہیں ایك ایسے آدمى كےبارےمیں نہ بتادیں) بایں طور كہ انہوں نے آپ صلی اللہ علیہ وسلم كى شخصیت كو غیر معروف بنادیا اور لوگوں كےسامنے اسطرح پیش كیا گویا كوئى مجہول شخص كسى مجہول امر كےبارےمیں كوئى خبردےرہاہو؟ تو اسكا میں یہ جواب دوں گا كہ اس سے انكا مقصد صرف استہزاء اور مذاق تھا، انہوں نے ایسا محض لہو ولعب اور دل كى تسلى كیلئے کہاتھا، آپ صلی اللہ علیہ وسلم كى شخصیت اور آپ كےپیغام کو انہوں نے جان بوجھ کر نظرانداز کردیاتھا۔ (القرطبى: ۱۷؍۲۵۷)\n(رجل)یعنى غیر معروف شخص كہہ كر انہوں نے نبى كریم صلی اللہ علیہ وسلم كے مسئلے سے تجاہل كیوں برتا؟\nwords\nيَلِجُوه داخل هوا.\nيَعرُجُوه چڑھتا هے.\nلاَ يَعزُبُوه غائب نهيں هوتا.\nعَذَابٌ مِن رِجزٍ أَلِيمٌبهت سخت برا او رتكليف ده عذاب.\nمُزِّقتُمتم مر جاؤ۔ اورتمهارے جسم كے اعضاء بكھر جائيں."],[429,"§سبإ\ndeeds\nآج اپنے سارے كام بڑى پختگى سے اسى طرح كریں جس سے الله راضى ہوجائے.\nقرآنى سورتوں كے یاد كرنے پر الله كے شكریے كے طور پر اپنے كسى مسلمان بھائى كو قرآن كى كوئى سورت سكھلائیے.\nدعا کیجئے: (اَللّٰهُمَّ اجْعَلْنِىْ مِنْ عِبَادِكَ الشَّاكِرِيْن) اے اللہ! ہمیں اپنے شکرگزار بندوں میں سے بنادے.\nguid\nالله كى طرف زیاده سے زیاده رجوع اور توبہ كرنا فطرتى نشانیوں سے استفاده كرنے كا ایك سبب ہے.\nكسى پیشے یا ہنر میں مہارت حاصل كرلیں تاكہ لوگوں سے بے نیاز رہیں.\nغیب كا علم صرف الله تعالىٰ ہى كو ہے.\nrefl\nأَفَلَمۡ يَرَوۡاْ إِلَىٰ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِن نَّشَأۡ نَخۡسِفۡ بِهِمُ ٱلۡأَرۡضَ أَوۡ نُسۡقِطۡ عَلَيۡهِمۡ كِسَفٗا مِّنَ ٱلسَّمَآءِۚ\nالله تعالىٰ نے یہ خبر دى ہے كہ جو ذات آسمان ، زمین اور ان میں موجود سارى چیزوں كى پیدائش پر قادر ہے وه ذات مخلوق كو دوباره اٹھائےجانے پر اور انہیں جلد عذاب دینے پر بھى قادر ہے، اس طرح اپنى قدرت سے ان پر استدلال كیا اور یہ كہ آسمان وزمین سب اسكى ملكیت ہیں، اور آسمان وزمین ہر چہار جانب سے ان كا احاطہ كئےہوئےہیں ، پھر وه زمین كے دھنسنے اور آسمان سے عذاب كے ٹكڑوں كے نازل ہونے سے بے خوف كیوں كر ہیں، كیا انہوں نے قارون اور جھاڑى والوں كا انجام نہیں دیكھا؟ (القرطبى: ۱۷؍۲۵۹)\nارض وسما ء کی پیدائش میں الله سبحانہ وتعالىٰ كى قدرت، نافرمانوں كو عذاب دینے كى قدرت پر كیسے دلالت كرتى ہے؟\nإِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّكُلِّ عَبۡدٖ مُّنِيبٖ ٩\nبندۂ مومن جس قدر الله تعالىٰ كى طرف رجوع كرےگا ، اسى قدر زیاده وه آیات الہى سے مستفید ہوگا ؛ كیونكہ الله تعالىٰ كى طرف رجوع كرنے والا الله كى طرف متوجہ ہوتاہے، اس كا اراده اور ہمت بھى الله تعالىٰ كى طرف متوجہ ہوتےہیں، اور وہ ہر معاملے میں اسى كى طرف رجوع كرتاہے اس طرح وہ اپنے رب كےقریب ہوجاتا ہے اور اپنے رب كى رضا میں مشغولیت كےسوا اس كا كوئى اراده نہیں ہوتا، مخلوقات پر اسكى نظر بے فائده اورغفلت كى نظر نہیں ہوتى بلكہ فكر وعبرت كى نظر ہوتى ہے۔ (السعدى: ۶۷۶)\nنشانیوں سے فائده اٹھانے كو الله كے نیك بندوں كےساتھ خاص كیوں كردیا گیا؟\n۞وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ مِنَّا فَضۡلٗاۖ يَٰجِبَالُ أَوِّبِي مَعَهُۥ وَٱلطَّيۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِيدَ ١٠\n(فضلًا) كو نكره لایا گیا اسكى عظمت كو بتلانے كیلئے، كیوں كہ یہ نبوت اور بادشاہت كا فضل ہے، اصلاح امت كے خیال كا فضل ہے، عدل كے فیصلے كا فضل ہے، لڑائى میں بہادرى كا فضل ہے، نعمت كى كشادگى كا فضل ہے، لوہے كا زره بنانے كا ہنر دیكر لوگوں سے بے نیاز كرنے كا فضل ہے، زبور كے دینے كا فضل ہے، خوش الحانى دینے كا فضل ہے اور نیكى كى خاطر درازئ عمر اور اس طرح كى دیگر نعمتوں كا فضل ہے۔ (القرطبى: ۱۷؍۲۶۳)\nآیت كریمہ كےاندر (فضلًا) كو نكره لانے كا كیا فائده ہے؟\nأَنِ ٱعۡمَلۡ سَٰبِغَٰتٖ وَقَدِّرۡ فِي ٱلسَّرۡدِۖ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ بَصِيرٞ ١١\nاس آیت میں اس بات كى دلیل ہے كہ صاحب فضیلت كو بھى پیشوں سے جڑے رہنا چاہئے، اور كوئى پیشہ اختیار كرنے سے انكے فضل ومرتبے میں كوئى كمى نہیں ہوگى، بلكہ یہ انكے فضل ومرتبے میں زیادتى كا باعث ہوگا؛ كیونكہ اس سے خاكسارى كا اظہار اور دوسروں سے بے نیازى كا اعلان ہے، اور ایسى حلال كمائى ہے جو كسى كے احسان كے شكر بجالانے سے خالى ہے۔ (القرطبى: ۱۷؍۲۶۳)\nطالب علم كا پیشے اور ہنر كا سیكھنا كیا عیب كى بات ہے؟\nٱعۡمَلُوٓاْ ءَالَ دَاوُۥدَ شُكۡرٗاۚ\nاس میں یہ دلیل ہے كہ شكر جس طرح سے قول ونیت كے ذریعے ہوتا ہے اسى طرح عمل سے بھى ہوتاہے، جیسا كہ شاعر نے كہا: أفادتكم النعماء مني ثلاثة* يدی ولساني والضمير المحجبا ۔ یعنى میرى طرف سے تم كو تین نعمتوں نے فائده پہونچایا: میرا ہاتھ ، میرى زبان اور چھپا ہوا دل۔ (ابن كثیر: ۳؍۵۰۷)\nوه كون سے ذرائع ہیں جن كے واسطے انسان اپنےرب كا شكریہ ادا كرتاہے؟\nٱعۡمَلُوٓاْ ءَالَ دَاوُۥدَ شُكۡرٗاۚ وَقَلِيلٞ مِّنۡ عِبَادِيَ ٱلشَّكُورُ ١٣\nمروى ہے كہ داؤدعلیہ السلام نے عرض كیا: اے میرے رب! میں تیرى نعمتوں پر كیسے شكریہ ادا كروں جبكہ میرا الہام اور شكر پرمیرى قدرت خود تیرى نعمت ہے؟ تو الله نے فرمایا: اے داؤد ! تو نے مجھے اب پہچانا۔ اور شكر كى حقیقت یہ ہے كہ منعم حقیقى كیلئے نعمت كا اعتراف كیا جائے اور اسے اسكى اطاعت میں استعمال كیا جائے۔ اور ناشكرى یہ ہے كہ اسے معصیت میں استعمال كیا جائے۔ اور بہت كم ہیں جو شکرادا كرتےہیں۔(القرطبى: ۱۷؍۲۷۸)\nشكر كى حقیقت واضح كریں، نیز بتلائیں كیا اہل شكر كى تعداد زیاده ہے؟\nفَلَمَّا قَضَيۡنَا عَلَيۡهِ ٱلۡمَوۡتَ مَا دَلَّهُمۡ عَلَىٰ مَوۡتِهِۦٓ إِلَّا دَآبَّةُ ٱلۡأَرۡضِ تَأۡكُلُ مِنسَأَتَهُۥۖ فَلَمَّا خَرَّ تَبَيَّنَتِ ٱلۡجِنُّ أَن لَّوۡ كَانُواْ يَعۡلَمُونَ ٱلۡغَيۡبَ مَا لَبِثُواْ فِي ٱلۡعَذَابِ ٱلۡمُهِينِ ١٤\nمطلب یہ ہے لوگوں پر یہ واضح ہوگیا كہ جنات غیب نہیں جانتے۔ اور كہاگیا: ان پر واضح ہوگیا یعنى انہیں معلوم ہوگیا۔ (ابن جزى: ۲؍۲۰۳)\nآپ ان پر كیسے رد كریں گے جو كہتےہیں كہ جنات غیب جانتےہیں؟\nwords\nكِسَفًاعذاب كا ايك حصه.\nمُنِيبٍتوبه اور اطاعت سے اپنے رب كي طرف رجوع كرنے والا.\nأَوِّبِي مَعَهُاس كے ساتھ تسبيح بيان كرو.\nوَقَدِّر فِي السَّردِان ديگوں كے كڑوں ميں كيليں لگاليں تاكه وه نه هي چھوٹے هوں نه هي بڑے.\nعَينَ القِطرِتانبے كا چشمه ۔ وهاں سے تانبا پاني كي طرح بهتا تھا.\nوَجِفَانٍ كَالجَوَابِبهت بڑا پياله /جيسے كه حوض ؛ اس ميں پاني جمع كيا جاتا تھا."],[430,"§سبإ\ndeeds\nالله كا شكریہ بجا لاتےہوئے كھانے سے پہلے بسم الله اور اسكے بعد الحمد لله كہیں.\nواقعۂ سبا كى آیتوں كى روشنى میں نعمتوں كى ناشكرى كے برے انجام میں سے تین انجام بتلائیں.\nایك پیغام بھیجیں جس میں اپنے رشتہ داروں اور ساتھیوں كو الله كے دین سے اعراض كرنے والوں كے حق میں الہى سزاؤں كو یاد دلائیں.\nguid\nالله كى نعمتوں كى ناشكرى كرنے سے بچیں.\nایسى دعا كریں جس سے آپ كو فائده ہو اور ایسى دعا سے بچیں جس سے آپ كو نقصان ہو.\nشیطان كے وسوسوں اور اسكے كچوكوں سے بچ كر رہیں.\nrefl\nلَقَدۡ كَانَ لِسَبَإٖ فِي مَسۡكَنِهِمۡ ءَايَةٞۖ\nسلیمان علیہ السلام كى خبر قوم سبا كے ذكر كا سبب بنى، كیونكہ سلیمان علیہ السلام كى بادشاہت اور قوم سبا كى بادشاہت میں بلقیس كے واقعہ كے سبب سے ایك وجہ اتصال پایا جاتاہے۔اور چونكہ قوم سبا كى حالت حضرت داؤد اور سلیمان -علیہما السلام- كى حالت سے یكسر متضاد ہے ؛ كیونكہ یہ دونوں شكر كرنےوالوں پر نعمت كى بارش كیلئے مثال ہیں، اور وه قوم كافروں سے نعمت كے چھننے میں مثال ہے۔ (ابن عاشور: ۲۲؍۱۶۵)\nسلیمان علیہ السلام كے قصے كےبعد قوم سبا كے قصے كو لانے كى مناسبات بیان كریں.\nفَأَعۡرَضُواْ فَأَرۡسَلۡنَا عَلَيۡهِمۡ سَيۡلَ ٱلۡعَرِمِ وَبَدَّلۡنَٰهُم بِجَنَّتَيۡهِمۡ جَنَّتَيۡنِ ذَوَاتَيۡ أُكُلٍ خَمۡطٖ وَأَثۡلٖ وَشَيۡءٖ مِّن سِدۡرٖ قَلِيلٖ ١٦\n(فَأَعرَضُوا) یعنى انہوں نے الله كا شكر بجالانے سے اعراض كیا، یا انبیاء كى اطاعت سے اعراض كیا۔ (ابن جزى: ۲؍۲۰۳)\nكیا معاملہ ہے جس كى وجہ سے قوم سبا نے اعراض كیا اور جس كے سبب انكى حالت بدل گئى؟\nوَبَدَّلۡنَٰهُم بِجَنَّتَيۡهِمۡ جَنَّتَيۡنِ ذَوَاتَيۡ أُكُلٍ خَمۡطٖ وَأَثۡلٖ وَشَيۡءٖ مِّن سِدۡرٖ قَلِيلٖ ١٦\nیہ سزا ان كے عمل كى جنس سے تھى یعنى جس طرح انہوں نے شكر حسن كو كفر قبیح میں بدل ڈالا اسى طرح ان كى وه نعمتیں بدل دى گئیں جن كا اوپر ذكر كیا گیا ہے۔(السعدى: ۶۷۷)\nآیت كریمہ كى روشنى میں (الجزاء من جنس العمل) قاعدے كے بارےمیں كلام كریں.\nوَجَعَلۡنَا بَيۡنَهُمۡ وَبَيۡنَ ٱلۡقُرَى ٱلَّتِي بَٰرَكۡنَا فِيهَا قُرٗى ظَٰهِرَةٗ وَقَدَّرۡنَا فِيهَا ٱلسَّيۡرَۖ سِيرُواْ فِيهَا لَيَالِيَ وَأَيَّامًا ءَامِنِينَ ١٨\nفرمان بارى:(وَقَدَّرنا فِيهَا السَّيرَ) سےوہى مراد ہے جس كا تذكره اوپر ہوا كہ حالت سفر میں ایك مسافر ایك بستى میں رات گزارتا اور دوسرى بستى میں قیلولہ كرتا چاہے وہ جس راہ کو بھی اختیار کرتا اسے كوئى تكلیف نہ ہوتى۔ اور فرمان بارى: (سِيرُوا) ، یعنى ہم نے ان سے كہا چلو پھرو ۔ اور (آمِنِينَ) یعنى فسادیوں كے خوف سے امن وامان كےساتھ، اور بھوك وپیاس اور دوران سفر دیگر مصیبتوں سے امن وامان كےساتھ۔ (ابن عطیہ: ۴؍۴۱۶)\nآیت كےاندر وارد دونوں جملوں: (وَقَدَّرنا فِيهَا السَّيرَ) اور(آمِنِينَ) سے كیا مراد ہے؟\nإِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ ١٩\n(الآيات) كو جمع لایا گیا كیونكہ قصے كےاندر بہت سارى نشانیاں اور عبرتیں ہیں، چنانچہ انكى بستیاں الله كى رحمت ، اور اسكى قدرت وانعام پرنشانى ہیں اور ان پر سیلاب بھیجنے میں نشانى ہے الله تعالىٰ كے تنہا تصرف پر، اور یہ كہ وہى تنہا انتقام لینے والا ہے۔ خوشحالى سے بدحالى میں ان كى حالت بدل جانے میں نشانى ہے حالات كى تبدیلى اور عالم كے تغیر پر ، اور اس میں یہ بھى نشانى ہے كہ انسان ایك حال پر مطمئن نہیں رہتا چاہے وه خیر ہو یا شر۔ ان كى سلطنت كى آبادى اور بلاد شام تك ان كى بستیوں كے پھیلنے میں نشانى ہے ان كى آبادى كى انتہا اور عظیم سلطنت پر، اور نشانى ہے اس بات پر كہ امن وامان آبادى كى بنیاد ہے۔ اور اس نعمت كے چھن جانے كى تمنا كرنے میں نشانى ہے اس بات پر كہ ان كى عقلیں كس قدر انحطاط كا شكار تھیں كہ جس كى وجہ سے قوم كى حالت بگڑ گئى اور سارى عظمت ختم ہوگئى، اور انكا وطن سے ادھر ادھر بكھر جانے اور ہجرت كرجانے میں نشانى ہے اس بات پر كہ انسان ایسى صورت میں كن خطرات اور پریشانیوں كا شكار ہوتاہے۔ اور دونوں صفت: (صبار) اور (شكور) كو ایك ساتھ لانے كا فائده یہ ہے كہ ایك مومن كیلئے ضرورى ہے كہ وه ان دونوں اخلاق سے متصف ہو ، یعنى تكالیف پر صبر كرنا ، اور نعمتوں پر شكربجالانا، اور یہ قوم سبا جن كےبارےمیں گفتگو چل رہى ہے یہ نعمتوں پر شكریہ اداكر نے كى بجائے الٹا اترانے لگےاور نعمتوں كے ختم ہوجانے پر صبر بھى نہیں كیا۔ (ابن عاشور: ۲۲؍۱۸۰)\nآیت كےاندر (الآيات) كو جمع كیوں لایا گیا ہے؟ اور ختم آیت پر (صبار) اور (شكور) دونوں صفت كو ایك ساتھ كیوں لایا گیا ہے؟\nوَلَقَدۡ صَدَّقَ عَلَيۡهِمۡ إِبۡلِيسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا فَرِيقٗا مِّنَ ٱلۡمُؤۡمِنِينَ ٢٠\nابن قتیبہ نے كہا: ابلیس نے جب مہلت مانگى تو الله نے اسے مہلت دیدى تو اس نے كہا: (میں انہیں سیدھے راه سے بھٹكا كر انہیں گمراه كردوں گا) چنانچہ جس وقت وه یہ بات كہہ رہا تھا اسے یقین نہیں تھا كہ اسكا یہ مقصد پورا ہوجائے گا ، بلكہ اس نے یہ بات ظن وتخمین كى بنیاد پر كہى تھى، لیكن جب لوگوں نے اس كى پیروى اور اطاعت كرلى تو انكےبارےمیں اسكا گمان سچ ہوگیا۔ حسن نے كہا: اس نے انہیں نہ تو تلوار سے مارا اور نہ ہى كوڑا سے بلكہ اس نے ان سے وعده كیا اور انہیں امید دلائى جس سے وه دھوكہ كھا گئے۔ (البغوى: ۳؍۶۰۴)\nواضح كریں كہ كیسے ابلیس كا گمان انكے بارےمیں سچ ثابت ہوگیا؟\nوَمَا كَانَ لَهُۥ عَلَيۡهِم مِّن سُلۡطَٰنٍ إِلَّا لِنَعۡلَمَ مَن يُؤۡمِنُ بِٱلۡأٓخِرَةِ مِمَّنۡ هُوَ مِنۡهَا فِي شَكّٖۗ وَرَبُّكَ عَلَىٰ كُلِّ شَيۡءٍ حَفِيظٞ ٢١\nابلیس نے انہیں كفر پر مجبور نہیں كیا، اس نے صرف انہیں دعوت دى اور اسے مزین كیا اسكے پاس ایسى كوئى حجت اور دلیل نہیں تھى كہ جس كى بنیاد پر اسكى پیروى كرتے بلكہ شہوت، تقلید اور خواہشات نفسانى كى بنیاد پر اسكى پیروى كى نہ كہ حجت اور دلیل كى بنیادپر۔ (البغوى: ۳؍۶۰۴)\nكیا ابلیس كےپاس كوئى ایسى طاقت ہے جس كى بنیاد پر وه انسان كو كفر اور معصیتوں پر مجبور كرتاہے؟\nwords\nآيَةٌهماري قدرت كي دليل.\nذَوَاتَيميرے مصاحب.\nسَيلَ العَرِمِوه سخت سيلاب جس نے اس ڈيم كو تباه كرديا؛ باغ بھي تباه هوگئے.\nأُكُلٍ خَمطٍايك كڑوا اور بد ذائقه پھل.\nوَأَثلٍجھاؤ سے ملتا جلتا ايك معروف بے پھل درخت.\nسِدرٍبيري كا درخت / بهت زياده كانٹے دار."]])